FBDMC_SetKinTransform(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_SetKinTransform *FB){
/*Separator--*--Separator--*--Separator*/
#ifndef _CASS_PRECOMPILE_

	struct AXESGROUP * axesgroup = &AxesGroup_Mem[FB->AxesGroup];
	uint8_t *axesgroup_state = (uint8_t*)(&axesgroup->ui8_AxesGroup_State);
	uint8_t *axesgroup_kin = (uint8_t*)(&axesgroup->ui8_Kin_Transform);
	uint8_t *axesgroup_busy = (uint8_t*)(&axesgroup->ui8_AxesGroup_Busy);
	uint8_t *axesgroup_run_next = (uint8_t*)(&axesgroup->ui8_AxesGroup_Run_Next);
	uint8_t *axis_sum_ingroup = (uint8_t*)(&axesgroup->ui8_Axis_Sum_In_Group);
    uint8_t *axesgroup_kin_axissum = (uint8_t*)(&axesgroup->ui8_Kin_Axis_Sum);

	int KinTransform_error;
	if( FB->Execute && (!FB->execute_before))
	{
		//if(*axesgroup_state == MC_GroupErrorstop)
		if(*axesgroup_state != MC_GroupDisabled)
		{//只有在disable状态下才可以修改运动学模型
			FB->Error = true;
			FB->ErrorID = StateError;
		}
		else
		{
			if((FB->ExecutionMode !=Immediately && FB->ExecutionMode != Delayed && FB->ExecutionMode != Queued )|| FB->AxesGroup >= AXESGROUP_MAXNUM || FB->AxesGroup < AXESGROUP_MINNUM)
			{
				FB->Error = true;
				FB->ErrorID = ParameterError;
			}
			else
			{
				KinTransform_error = 0;
				FB->Error = false;
				FB->ErrorID = NoError;
				FB->Busy = true;
				FB->run = true;//绑定运动学模型  需要execute激活
				FB->run_flag = false;
                FB->axesgroup_init_flag = false;
			}
		}
	}
	FB->execute_before = FB->Execute;

	//判断绑定运动学模型的执行方式
	if(FB->run)
	{
		//立即执行
		if(Immediately == FB->ExecutionMode)
		{
			FB->run_flag = true;
			FB->run = false;
            FB->axesgroup_init_flag = false;
		}
		//当前正在进行的运动任务完成后，延迟执行
		else if(Delayed == FB->ExecutionMode)
		{
			/**等轴组当前这个运动任务执行完成 或者 轴组空闲*/
			if((*axesgroup_busy == 1 && *axesgroup_run_next == 1) || *axesgroup_busy == 0 )
			{
				FB->run_flag = true;
				FB->run = false;
                FB->axesgroup_init_flag = false;
			}

		}
		//所有之前的运动指令全部执行完成，队列执行
		else if(Queued == FB->ExecutionMode)
		{
			/**等前面的所有的任务执行完成*/
			if(*axesgroup_busy == 0)//所有之前的运动指令全部完成的下一个周期
			{
				FB->run_flag = true;
				FB->run = false;
                FB->axesgroup_init_flag = false;
			}
		}
	}

	 //每种机器人运动学模型的都不一样；
	 ///给不同的运动学模型从2开始加上编号;
	 /// 暂不使用：1表示不选择运动学模型或使用之前绑定好的运动学模型，即只是修改参数
	///判断轴组内的单轴数是否满足运动学模型要求，不满足则报错;
    if(FB->KinTransform != 0 && FB->run_flag == true)
	{
	    //选择模型+修改参数（也可使用默认参数）
		FB->run_flag = false;
		KinTransform_error = 0;
		switch(FB->KinTransform)
		{
			case PUMA_A6:
			    if(PUMA_A6_AXIS_SUM == *axis_sum_ingroup)
                {
                    *axesgroup_kin = PUMA_A6;
                    *axesgroup_kin_axissum = PUMA_A6_AXIS_SUM;
			    }
			    else
                {
                    KinTransform_error = 1;
                    FB->ErrorID = AxisSum_InAxesGroup_Error;
                }

				break;

			case PR_A4:
			     if(PR_A4_AXIS_SUM == *axis_sum_ingroup)
                {
                    *axesgroup_kin = PR_A4;
                    *axesgroup_kin_axissum = PR_A4_AXIS_SUM;
			    }
			    else
                {
                    KinTransform_error = 1;
                    FB->ErrorID = AxisSum_InAxesGroup_Error;
                }
				break;

			case Three_A3:
			     if(Three_A3_AXIS_SUM == *axis_sum_ingroup)
                {
                    *axesgroup_kin = Three_A3;
                    *axesgroup_kin_axissum = Three_A3_AXIS_SUM;
			    }
			    else
                {
                    KinTransform_error = 1;
                    FB->ErrorID = AxisSum_InAxesGroup_Error;
                }
				break;
			case PR_CSR6:
			     if(PR_CSR6_AXIS_SUM == *axis_sum_ingroup)
                {
                    *axesgroup_kin = PR_CSR6;
                    *axesgroup_kin_axissum = PR_CSR6_AXIS_SUM;
			    }
			    else
                {
                    KinTransform_error = 1;
                    FB->ErrorID = AxisSum_InAxesGroup_Error;
                }
				break;
			case PR_SCARA:
			     if(PR_SCARA_AXIS_SUM == *axis_sum_ingroup)
                {
                    *axesgroup_kin = PR_SCARA;
                    *axesgroup_kin_axissum = PR_SCARA_AXIS_SUM;
			    }
			    else
                {
                    KinTransform_error = 1;
                    FB->ErrorID = AxisSum_InAxesGroup_Error;
                }
				break;
			default:
				KinTransform_error = 1;
				FB->ErrorID = KinTransform_ParameterError;
				console_printf("\n% axis_sum_ingroup error .\n",FB->KinTransform);
				break;
		}

        for(int id = 0; id < *axis_sum_ingroup; id++)
        {
            if(FB->ShaftRevolution[id] == 0)
            {
                KinTransform_error = 1;
                FB->ErrorID = ParameterError;
                console_printf("\nFB->ui32_Joint_ShaftRevolution[id] == 0,无法当除数\n");
                break;
            }
        }

		if(1 == KinTransform_error)
		{
            FB->axesgroup_init_flag = false;
			FB->Done = false;
			FB->Error = true;
            FB->Busy = false;
            FB->Active = false;
            FB->CommandAborted = false;
		}
		else
		{
           // console_printf("\n ##1 Init_AxesGroup_KinTransform-axesgroup->ui8_Kin_Transform = %d \n",axesgroup->ui8_Kin_Transform);
		    //Init_AxesGroup_KinTransform(axesgroup); ///初始化轴组的运动学模型的固定参数！！！
		    for(int id = 0; id < *axis_sum_ingroup+1; id++)
            {
                axesgroup->f32_DenHartA[id] = FB->DenHartA[id]	;   /**f32  该轴组绑定的运动学模型需要的DH参数*/       //开放给用户自定义
                axesgroup->f32_DenHartD[id] = FB->DenHartD[id]	;   /**f32  该轴组绑定的运动学模型需要的DH参数*/       //开放给用户自定义
            }

            for(int id = 0; id < *axis_sum_ingroup; id++)
            {
                axesgroup->i8_JointDirections[id] = FB->JointDirections[id];  /**ui8  该轴组绑定的运动学模型（机器人）每个轴的电机旋转方向  顺时针或者逆时针 默认为1--顺时针旋转2--逆时针旋转 */  //开放给用户自定义
                axesgroup->i32_JointOffsets[id] =  FB->JointOffsets[id]; /**ui32 该轴组绑定的运动学模型（机器人）  的每个轴的电子零点和机械零点的偏移量=（控制器读取到的）电子零点-机械当前位置*/       //开放给用户自定义
                axesgroup->ui32_Joint_MotorRevolution[id] =  FB->MotorRevolution[id];
                axesgroup->ui32_Joint_ShaftRevolution[id] =  FB->ShaftRevolution[id];       //开放给用户自定义
                axesgroup->d64_JointGearRatios[id] =  FB->MotorRevolution[id] * 1.0 / FB->ShaftRevolution[id];    //开放给用户自定义

            }
            for(int id = 0; id < (*axis_sum_ingroup * 2); id++)
            {
                axesgroup->f32_JointLimits[id] =  FB->JointLimits[id];    //角度限制开放给用户自定义
            }

            FB->axesgroup_init_flag = true;
           // console_printf("Init_AxesGroup_KinTransform-finish axesgroup->d64_JointGearRatios = %f, =%f, =%f, =%lf\n",axesgroup->d64_JointGearRatios[0],axesgroup->d64_JointGearRatios[1],axesgroup->d64_JointGearRatios[2],axesgroup->d64_JointGearRatios[3]);
		}

	}
    else{}//配套if使用

    //根据运动学模型，初始化轴组结构体成员（位置、等
    if(true == FB->axesgroup_init_flag)
    {
      //  console_printf("\n******FBDMC_SetKinTransform  if(true == FB->axesgroup_init_flag) \n");
        FB->axesgroup_init_flag = false;

        //轴组当前位置: 每个轴的实际位置（*now_position[j]脉冲）=》角度 =》MCS的位姿
        double axis_now_angle[AXIS_SUM_INGROUP_MAX];
        int axis_n;
        double axis_now_position;
        double* axis_now_position_p;
        for (int id = 0; id < *axis_sum_ingroup; id++) {
            axis_n = axesgroup->i16_Axis_Num_In_Group[id];//id =》实际单轴号

            //每个轴当前脉冲值
            axis_now_position_p = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + NOW_POSITION]);
            axis_now_position = *axis_now_position_p;
           // console_printf(" AxisNum=%d axis_now_position =%lf  axesgroup->i32_JointOffsets[id] = %d, axesgroup->d64_JointGearRatios[id] = %lf\n",axis_n,axis_now_position,axesgroup->i32_JointOffsets[id],axesgroup->d64_JointGearRatios[id]);
            axis_now_angle[id] = (axis_now_position - axesgroup->i32_JointOffsets[id]) *
                                 (axesgroup->i8_JointDirections[id])*1.0 /
                                 (axesgroup->d64_JointGearRatios[id]);
         //   console_printf("-------------axis_now_angle[%d] =%lf \n",id,axis_now_angle[id]);


            //初始化轴组结构体成员
            axesgroup->f32_Now_Axis_Motion_AimPulse[id] = axis_now_position;
        }
        double MCS_X;
        double MCS_Y;
        double MCS_Z;
        double MCS_RX;
        double MCS_RY;
        double MCS_RZ;

        ACS_MCS_KinTransform(Task,FBIndex,axesgroup->ui8_Kin_Transform, 1, axis_now_angle, &MCS_X, &MCS_Y, &MCS_Z, &MCS_RX, &MCS_RY,
                             &MCS_RZ, axesgroup->f32_JointLimits, NULL , &FB->Error_, &FB->ErrorID, axesgroup->f32_DenHartA,
                             axesgroup->f32_DenHartD);

        //console_printf(" ACS_MCS_KinTransform-finished init axesgroup Now_TCP_Position \n");
       // FB->Error , FB->ErrorID = ACS_MCS_KinTransform();
       if ( FB->Error == 0)
        {
            axesgroup->f32_Now_TCP_Position[0] = MCS_X;
            axesgroup->f32_Now_TCP_Position[1] = MCS_Y;
            axesgroup->f32_Now_TCP_Position[2] = MCS_Z;
            axesgroup->f32_Now_TCP_Position[3] = MCS_RX;
            axesgroup->f32_Now_TCP_Position[4] = MCS_RY;
            axesgroup->f32_Now_TCP_Position[5] = MCS_RZ;

            //初始化轴组结构体成员
            for(int f=0;f<POSITION_SIZE;f++)
            {
                axesgroup->f32_Now_TCP_Motion_Aimpos[f] = axesgroup->f32_TCP_Target_Position[f] = axesgroup->f32_TCP_Last_Target_Position[f] = axesgroup->f32_TCP_Last_Last_Target_Position[f] = axesgroup->f32_Now_TCP_Position[f];
                console_printf("TCP_Target_Position[%d] = %lf \n",f,axesgroup->f32_TCP_Target_Position[f]);
            }
            FB->Done = true;
        }
        axesgroup->ui8_Axesgroup_Init_Finish = 1;

        FB->Busy = false;
        FB->Active = false;
        FB->CommandAborted = false;
        //console_printf("\nFBDMC_SetKinTransform-done=true-------------------\n");
    }

	//该FB不在使用状态
	if(!FB->Execute)
	{
		FB->Done = false;
		FB->Busy = false;
		FB->Active = false;
		FB->CommandAborted = false;
		FB->Error = false;
		FB->ErrorID = 0;
		FB->run_flag = false;
		FB->run = false;
        FB->axesgroup_init_flag = false;
	}

	FB->AxesGroupOut = FB->AxesGroup;
#endif
}

FBDMC_Reset(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_Reset *FB){
/*Separator--*--Separator--*--Separator*/
//FBDMC_Reset
#ifndef _CASS_PRECOMPILE_




//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量

uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
uint8_t *AxisEnable = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_ENABLE]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);
unsigned short *driver_controlword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_CONTROLWORD]);
unsigned short *statusword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_STATUSWORD]);
uint8_t *rstflag = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RST_FLAG]);
uint8_t *couping_mode = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + COUPING_MODE]);

uint8_t *torque_run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_RUN_NUMBER]);

float *now_velocity_s = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_VELOCITY_S]);

uint8_t *axis_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_BUSY]);

int32_t *now_motion_direction = (int32_t*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_DIRECTION]);
float *blending_v = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + BLENDING_V]);
float *now_motion_vel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_MOTION_VEL]);
uint8_t *buffered_without_blending = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFERED_WITHOUT_BLENDING]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);

Uint8 busy;
//结构体里没有busy变量。只能从exebef变量的字节中借一个！！！功能块的结构是定死的，没法加变量！！！！！
busy = (FB->execute_before >> 7);/* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
FB->execute_before &= 0x7f;

if(!FB->Execute)//不在被使用状态
{
	FB->Done = false;
	FB->Error = false;
	FB->ErrorID = 0;
}

if(FB->Execute && !FB->execute_before)
{
    if(FB->Axis_num >= AXIS_MAXNUM)
	{
		FB->Error = true;
		FB->ErrorID = ParameterError;
	}
	else
    {
        *AxisEnable = true;
        if(*state != MC_Errorstop && *state != MC_Standstill && *state != MC_Disabled)
        {
            FB->Error = true;
			FB->ErrorID = StateError;
        }
        else
        {
            FB->Error = false;
            FB->ErrorID = NoError;
        }

    }

    if(!FB->Error)
    {
        *rstflag = 1;//rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作
        busy = 1;//进行复位
    }
    //console_printf("MC_Reset: Axis %d reset command , FB->Error = %d ! \n ", FB->Axis_num,FB->Error) ;
}

if (busy) /* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
{
    *axis_busy = 0;
    *now_motion_vel = 0;

    *state = MC_Disabled;
    *run_numberm  = 0;//轴上没有运动
    *torque_run_numberm = 0;
    *couping_mode = 0;
    *now_motion_direction = 0;
    *blending_v = 0;
    *buffered_without_blending = 0;
    *buffer_busy = 0;
   if ((*statusword & SwFault) != SwFault && *statusword != 0 )//没有故障
    {
        FB->Done = true;
        FB->Error = false;
        FB->ErrorID = 0;
        busy = 0;
    }
    else
    {
            FB->Error = true;
			FB->ErrorID = StateError;
    }

}
FB->execute_before = (FB->Execute + (busy << 7) );//最高位保存busy变量

FB->Axis_numOut = FB->Axis_num;

#endif
}

