            phasing_velocity[FB->i] = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + PHASING_VELOCITY]);
            phasing_runnext[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + PHASING_RUNNEXT]);
            phasing_busy[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + PHASING_BUSY]);
            //sup_motion_flag[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + SUP_MOTION_FLAG]);


            *target_position[FB->i] = *now_position[FB->i];
            *last_target_position[FB->i] = *target_position[FB->i];
            *now_motion_aimpos[FB->i] = *now_position[FB->i];
            *sup_position[FB->i] = 0;
            *torque_last_read_pos[FB->i] = *(double *)actual_position[FB->i];
            *torque_last_velocity[FB->i] = 0;
            *write_target_velocity[FB->i] = 0;
            *now_velocity_s[FB->i] = 0;


        }
    }

     FB->EnLast = FB->Enable;
    FB->Done = 1 ;


	//YJZ2024/7/9增加：新增lstmid变量用于判断主从当前位置在数组中发生变化
	//int lastmid;
	//uint8_t *lastmid[AXIS_MAXNUM];

    //遍历每一个轴号  耦合运动的数据计算  每个周期开始的时候都要执行一次
    for (FB->i = 0; FB->i < AXIS_MAXNUM; FB->i++)
    {
        if ( *AxisEnable[FB->i] != true ) continue;
        *phasing_now_position[FB->i] = *phasing_target_position[FB->i];//相移当前的位置=上一时刻的目标位置   *phasing_target_position[FB->i]保存的是轴上一时刻的目标位置，当前时刻的值还没开始计算
        *phasing_velocity[FB->i] =
                (*phasing_target_position[FB->i] - *phasing_last_target_position[FB->i])*((float)1000/Task->taskPeriod);//相移当前的速度，时间为1ms，省略不写
        *phasing_last_target_position[FB->i] = *phasing_target_position[FB->i];//相移的上一时刻的目标位置
        if (*phasing_velocity[FB->i] == 0)//修改 原代码：if(*phasing_velocity[FB->i] = 0)//相移的速度为0，说明轴没发生相移，busy为0
        {
            *phasing_busy[FB->i] = 0;
        }
        /*
        if (*couping_mode[FB->i] == 2)    //齿轮gear  //当前轴被gear耦合，是从轴
        {//当前的从轴的目标位置=建立耦合关系后从轴的开始位置+（上一时刻的主轴的目标位置+主轴叠加运动的位置+在从轴角度看的主轴的相移距离-同步开始时主轴的位置）*齿轮比
            *target_position[FB->i] = *slave_start_position[FB->i] + (*target_position[*couping_master[FB->i]] +
                                                                      *sup_position[*couping_master[FB->i]] -
                                                                      *master_start_position[*couping_master[FB->i]]) *
                                                                     *gear_ratio[FB->i] + *phasing_now_position[FB->i];
        }
*/
        //轴当前的实际位置  DRIVE->AXIS
        if ( *pulse_ratio[FB->i] < 1 || *angle_ratio[FB->i] < 1.0e-6 ) { *pulse_ratio[FB->i] = 1 ;*angle_ratio[FB->i] = 1 ;} //分子或分母为0的情况，则分子分母同时改为1，相当于比例关系为1，也就是直接脉冲控制
       *now_position[FB->i] = (double)*actual_position[FB->i] / *pulse_ratio[FB->i] * *angle_ratio[FB->i];//- *sup_position[FB->i]; 20241101修改
    }
    //遍历每一个轴号  处理AXIS和DRIVE之间的实际/目标位置和速度的单位转换还有一些其他变量的状态更新  如：AXIS从DRIVE中获得实际位置   DRIVE从AXIS中获得目标位置在下一个for循环
    for (FB->i = 0; FB->i < AXIS_MAXNUM; FB->i++)
    {
        if ( *AxisEnable[FB->i] != true ) continue;
        *positive_torque_limit[FB->i] = ((unsigned short) *pos_torque_limit[FB->i]);//把AXIS中的正向力矩限制写进DRIVE
        *negative_torque_limit[FB->i] = ((unsigned short) *neg_torque_limit[FB->i]);

        //20240707,驱动器目标速度PDO写入方式修改
        if (*read_mode_operation[FB->i] == DRV_VEL_PROFILE_MODE )
        {
           *aim_velocity[FB->i] = *aim_velocity[FB->i]/1000 ; //毫秒单位，系统中每个毫秒计算一次，为了跟其它地方统一。

        }
        else if(*read_mode_operation[FB->i] == Torque_Mode)
        {
            //*aim_velocity[FB->i] = *aim_velocity[FB->i]/1000 ; //毫秒单位，系统中每个毫秒计算一次，为了跟其它地方统一。
        }
        else if( *read_mode_operation[FB->i] == Position_Mode)
        {
            //20240901修改*aim_velocity[FB->i] = (*target_position[FB->i] - *last_target_position[FB->i])*((float)1000/Task->taskPeriod);//写进AXIS。轴的目标速度=目标位置-上一次的目标位置  时间为1ms，省略不写
            *aim_velocity[FB->i] = (*target_position[FB->i] + *sup_position[FB->i]- *last_target_position[FB->i])*((float)1000/Task->taskPeriod);//写进AXIS。轴的目标速度=目标位置-上一次的目标位置  时间为1ms，省略不写

        }

        if (VELOCITY_RETURN ==
            1)//VELOCITY_RETURN：ethercat的通信变量，决定了AXIS读取电机速度的方式,以及将目标速度写给DRIVE的方式   为0时包括轴当前的实际位置的换算（drive->axis)，1不包括，文件CassSysVar里定义的宏为0
        {

                //actual_velocity：drive中的电机的实际速度    实际速度：drive->AXIS  目标速度：/axis->drive
                    *now_velocity_s[FB->i] = *actual_velocity[FB->i] / (DRIVER_VELOCITY_RATIO * *pulse_ratio[FB->i] )* *angle_ratio[FB->i];//drive->AXIS
                    *write_target_velocity[FB->i] = (int32_t) (*aim_velocity[FB->i]  / *angle_ratio[FB->i] * DRIVER_VELOCITY_RATIO *  *pulse_ratio[FB->i] *  1000);//axis->drive

        }
        else if (VELOCITY_RETURN == 0) {//actual_position:DRIVE中的电机实际速度
           // *torque_last_velocity[FB->i] = *actual_position[FB->i] -
            //                               *torque_last_read_pos[FB->i];//上一次的力矩速度=实际位置-上一次位置 *torque_last_read_pos[FB->i] = *actual_position[FB->i];
            if (*read_mode_operation[FB->i] == Torque_Mode)//力矩模式  DRIVE->AXIS  轴当前的实际速度
            {
                *now_velocity_s[FB->i] = *aim_velocity[FB->i] ;   //直接使用目标速度
            }
            else if (*read_mode_operation[FB->i] == DRV_VEL_PROFILE_MODE )    //20240707 added
            {
                *now_velocity_s[FB->i] = *actual_velocity[FB->i] / *pulse_ratio[FB->i] * *angle_ratio[FB->i];  //获取实际速度
                *now_velocity_s[FB->i] = *now_velocity_s[FB->i] /1000;
            }
            else////非力矩模式	AXIS->AXIS
            {
                double tmp ;
                tmp = (*target_position[FB->i] + *sup_position[FB->i] - *last_target_position[FB->i]) ;
                *now_velocity_s[FB->i] = tmp *((float)1000/Task->taskPeriod) ;
               // *now_velocity_s[FB->i] *= ((float)1000/Task->taskPeriod) ;
            }
            *write_target_velocity[FB->i] = (int32_t) (*aim_velocity[FB->i]  / *angle_ratio[FB->i] * *pulse_ratio[FB->i]  * 1000);
        }

        //在单轴更新前，保存一些轴组会使用到的数据
        backup_last_target_position[FB->i] = *last_target_position[FB->i];
        //状态更新/初始化    毕竟这个for循环每个周期开始都会执行一次
        *run_next[FB->i] = 0;
        *phasing_runnext[FB->i] = 0;
        *max_velocity[FB->i] = ((uint32_t) (fabs(*write_target_velocity[FB->i])));//最大速度=传给驱动器的目标速度
        *write_target_torque[FB->i] = ((short int) *target_torque[FB->i]);//目标力矩 AXIS->DRIVE
        *actual_torque[FB->i] = ((float) *dirver_actual_torque[FB->i]);//轴当前的实际力矩：DRIVE->AXIS
        *statusword[FB->i] = *driver_statusword[FB->i];//轴的状态字：DRIVE->AXIS
        *last_target_position[FB->i] = *target_position[FB->i] + *sup_position[FB->i];//上一时刻的目标位置
        *now_velocity[FB->i] = *now_velocity_s[FB->i];//轴的当前的速度
        *torque_last_read_pos[FB->i] = *actual_position[FB->i];//记录位置，前面13337行会用到
    }

    //遍历每一个轴号 轴状态的自动切换
    for (FB->i = 0; FB->i < AXIS_MAXNUM; FB->i++) {



        if ( *AxisEnable[FB->i] != true ) continue;
        //这里是进行smallsystem里的轴参数的复位(FB_MCReset无法访问的参数）；FB_MCReset可以访问的参数在FB_MCReset里复位
        if (*rst_flag[FB->i] == 1)                //reset  进行复位操作，复位状态
        {
            *rst_flag[FB->i] = 0;
            *now_velocity_s[FB->i] = 0;
            *sup_position[FB->i] = 0;
            //*sup_motion_flag[FB->i] = 0;//20240901修改 增加
            *write_target_velocity[FB->i] = 0;
            *torque_last_velocity[FB->i] = 0;
            *driver_controlword[FB->i] = Driver_Reset;//写给驱动器的控制字
            *target_position[FB->i] = *now_position[FB->i];
            *last_target_position[FB->i] = *target_position[FB->i];
            *now_motion_aimpos[FB->i] = *target_position[FB->i];
            *write_target_position[FB->i] = *actual_position[FB->i];
            *torque_last_read_pos[FB->i] = *actual_position[FB->i];
        }
        else//复位结束  或者  不在复位状态
        {
            if ((*driver_statusword[FB->i] & SwFault) == SwFault)//当前状态字为故障，轴的状态变为MC_Errorstop
            {
                *state[FB->i] = MC_Errorstop;
            }//下面的else意思是，当前不在复位过程中，也没有错误
                //else if((*driver_statusword[FB->i] & SwFault) != SwFault && *state[FB->i] == MC_Errorstop)
            else /* 2022年4月16日 modi 原来的cw赋值放在外面，而复位（128）又只写一次，会导致，ecat只传输一个周期的复位（128），然后就改cw。现在会等到复位完成再做cw赋值。 */
            {   /* 此处cw赋值的含义可视为使MC_Power的操作有效，只有错误被复位，MC_Power才会有效。 */
                if (*state[FB->i] == MC_Errorstop)//复位后/不在复位过程中，状态字不是故障，轴从错误状态变成禁用    如果还有错误，后面再变回errorstop就行了
                    *state[FB->i] = MC_Disabled;

                *driver_controlword[FB->i] = *controlword[FB->i];//把AXIS中的控制写给驱动器控制字
            }
            //*driver_controlword[FB->i] = *controlword[FB->i]; 上移

            *write_mode_operation[FB->i] = *mode[FB->i];//驱动器的控制模式：从AXIS写给驱动器
            *driver_homingmode[FB->i] = *homingmode[FB->i] ;

           if ( *read_mode_operation[FB->i] != Position_Mode )  //驱动器本身运动模式下，所有的位置都为驱动器当前位置 //20241224
            {
                *now_motion_aimpos[FB->i] = *now_position[FB->i];
                *target_position[FB->i] = *now_position[FB->i];
                *last_target_position[FB->i] = *target_position[FB->i];
                *sup_position[FB->i] = 0;
            }
        }


                //实际目标位置=（轴的底层运动目标位置+叠加运动位置  ）* 比例换算
        mid_var =  (*target_position[FB->i] + *sup_position[FB->i]) / *angle_ratio[FB->i] * *pulse_ratio[FB->i];
        if (mid_var > 0) *write_target_position[FB->i] = (long long )(mid_var+0.5);//写给驱动器的目标位置
        else *write_target_position[FB->i] = (long long )(mid_var-0.5);

        if  ((fabs( *write_target_position[FB->i] - *actual_position[FB->i]) < 1
                || fabs(*target_position[FB->i]  - *now_position[FB->i] )< minp / *angle_ratio[FB->i] * *pulse_ratio[FB->i]
                || fabs(*target_position[FB->i]  - *last_target_position[FB->i]) < minp / *angle_ratio[FB->i] * *pulse_ratio[FB->i])
                && *state[FB->i] != MC_Continuous_Motion && *state[FB->i] != MC_Errorstop && *state[FB->i] != MC_Disabled
                && *state[FB->i] != MC_Synchronized_Motion && *state[FB->i] != MC_Stopping && *axis_busy[FB->i] == 0 ) {//当前的目标位置==当前实际位置 => 轴没有发生移动
                if (*state[FB->i] != MC_Standstill)
                {
                    *state[FB->i] = MC_Standstill;//轴处于待机状态
                    //console_printf(RED "DriverSync #1: *state[FB->i]= %d,*target_position[FB->i] =%lf, *sup_position[FB->i]=%lf\n" NONE,*state[FB->i],*target_position[FB->i],*sup_position[FB->i]);

                }
                else
                {
                    *now_motion_aimpos[FB->i] = *now_position[FB->i];
                    //*target_position[FB->i] = *now_position[FB->i];
                    //*last_target_position[FB->i] = *target_position[FB->i];
                    if ( *super_busy[FB->i] == false  && *sup_position[FB->i] != 0 ) {
                        //console_printf(RED "DriverSync #2: *state[FB->i] = %d,*target_position[FB->i] =%lf, *sup_position[FB->i]=%lf\n" NONE,*state[FB->i],*target_position[FB->i],*sup_position[FB->i]);
                        *target_position[FB->i] += *sup_position[FB->i];
                        *sup_position[FB->i] = 0;
                    }
                }
            }


        // if(*sup_motion_flag[FB->i] == 1 && *axis_busy[FB->i] == 1)//20240901修改 增加
        // {
        //     //*target_position[FB->i] = *target_position[FB->i] + *sup_position[FB->i];//20240901修改 增加
        //     *last_target_position[FB->i] = *target_position[FB->i];
        // }
        // else if(*sup_motion_flag[FB->i] == 2 && *axis_busy[FB->i] == 1)
        // {
        //     *sup_motion_flag[FB->i] = 0;
        //     //*target_position[FB->i] = *target_position[FB->i] + *sup_position[FB->i];//20240901修改 增加
        //     *sup_position[FB->i] = 0;
        //     *last_target_position[FB->i] = *target_position[FB->i] + *sup_position[FB->i];
        // }

    }


#ifdef _FBDMC_COORDINATE
    //0、未写完 初始化所有轴组以及路径 AxesGroup_Mem[AXESGROUP_MAXNUM] MC_Path[PATH_MAXNUM]  static 使用静态变量，只初始化一次
    static int Init_All_AxesGroup = 0;// 初始化所有轴组 static 使用静态变量，只初始化一次
    if(0 == Init_All_AxesGroup)
    {
        //此时轴组里还没有单轴，还没有绑定运动学模型，不知道初始位置，只初始化部分轴组的属性; 位置信息需要在初始化完运动学模型才知道
        Init_All_AxesGroup = 1;
        for (int m = 0; m < PATH_MAXNUM; m++)
        {
            MC_Path_Points[m].ui8_PathValid = 0;
        }
        ///创建轴组，不绑定运动学模型，不需要初始化运动学模型的信息
        for (int m = 0; m < AXESGROUP_MAXNUM; m++)
        {
            AxesGroup_Mem[m].ui8_Valid = 0;
            AxesGroup_Mem[m].ui8_Axesgroup_Init_Finish = 0;
            AxesGroup_Mem[m].ui8_Axesgroup_GroupError = 0;
            AxesGroup_Mem[m].ui16_Axesgroup_GroupErrorID = NoGroupError;
            for(int id = 0; id < AXIS_MAXID_INGROUP; id++)
            {
                AxesGroup_Mem[m].i16_ErrorAxisID[id] = -1;      //i16 -1 表示没错*
            }

            AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupDisabled;
            AxesGroup_Mem[m].ui8_AxesGroup_Reset_Flag = 0;
            AxesGroup_Mem[m].ui8_AxesGroup_Run_Number = 0;
            AxesGroup_Mem[m].ui8_Axis_Sum_In_Group = 0;       //ui8 轴组包含的实际的单轴数量*
            for(int id = 0; id < AXIS_MAXID_INGROUP; id++)
            {
                AxesGroup_Mem[m].i16_Axis_Num_In_Group[id] = AXIS_IDLEID_INGROUP;      //i16 轴组里保存的轴号 初始化为 AXIS_IDLEID_INGROUP -1 表示没使用*
            }

            AxesGroup_Mem[m].ui8_AxesGroup_Busy = 0;         //ui8 当前轴组忙碌标志 *
            AxesGroup_Mem[m].ui8_AxesGroup_Buffer_Busy = 0;     //ui8  轴组的缓冲区是否繁忙*
            AxesGroup_Mem[m].ui8_AxesGroup_Run_Next = 0;       //ui8 当前FB运行完成置1，每个周期开始的时候都会被置0 *

            AxesGroup_Mem[m].ui8_Kin_Transform = 0;          //ui8 该轴组绑定的运动学模型  MCS和ACS的变换*

            AxesGroup_Mem[m].ui8_Coord_Transform = 0;          //ui8 MC_SetCoordinateTransform 和 MC_SetCartesianTransform设置MCS和PCS的变换（旋转+平移）方式*

            AxesGroup_Mem[m].ui8_PCS_Valid = 0;                  //ui8 当前是否存在PCS和MCS的变换方式*

            ///RELATIVE_POSITION                //FLOAT ACS MCS PCS 和实际原点的相对偏移量: 三个位置量+3个姿态（方向）量  -- X Y Z RX RY RZ *
            for(int id = 0; id < POSITION_SIZE; id++)
            {
                AxesGroup_Mem[m].f32_PCS_Relative_position[id] = 0;      //f32 PCS和实际原点的相对偏移量*
            }
            for(int id = 0; id < POSITION_SIZE; id++)
            {
                AxesGroup_Mem[m].f32_MCS_Relative_position[id] = 0;      //f32 MCS和实际原点的相对偏移量*
            }
            for(int id = 0; id < AXIS_MAXID_INGROUP; id++)
            {
                AxesGroup_Mem[m].f32_ACS_Relative_position[id] = 0;      //f32 ACS和实际原点的相对偏移量*
            }

            AxesGroup_Mem[m].ui8_Now_Motion_Type = NO_TYPE ;           //ui8 当前轴组运动的类型  PTP ，LINE，CIRCLE*/
            //只保存轴组 TCP 在 MCS 中的位置，速度，加速度；单轴的 ACS 运动信息会保存在单轴中
            AxesGroup_Mem[m].f32_Now_TCP_Velocity= 0;            //f32 当前轴组的速度   TCP_V 初始值为0*
            AxesGroup_Mem[m].f32_Now_TCP_Acceleration = 0 ;          //f32 当前轴组的加速度   TCP_A 初始值为0*

            AxesGroup_Mem[m].f32_Now_TCP_Motion_Velocity = 0 ;          //f32 初始值为0*
            for(int id = 0; id < 3; id++)
            {
                AxesGroup_Mem[m].f32_Now_TCP_Motion_Direction_Distance[id] = 0;
            }

            AxesGroup_Mem[m].ui8_ConstantVelocity = 0;  //是否在匀速运动
            AxesGroup_Mem[m].ui8_Accelerating = 0;  //是否在加速
            AxesGroup_Mem[m].ui8_Decelerating = 0;  //是否在减速
            AxesGroup_Mem[m].ui8_InPosition = 0;  ///是否到达目标位置  运动开始前置1，结束置0

            AxesGroup_Mem[m].f32_VelFactor = 1;  //速度因子值为0时，轴停止运动，但是状态不会变为standby
            AxesGroup_Mem[m].f32_AccFactor = 1;//加速度因子作用于加速度和减速度，值为0时报错
            AxesGroup_Mem[m].f32_JerkFactor = 1;//加加速度因子作用于加加速度，值为0时报错

            AxesGroup_Mem[m].ui8_Buffer_Motion_Type = NO_TYPE ;           //ui8 缓冲区的轴组运动的类型  PTP ，LINE，CIRCLE*/
            AxesGroup_Mem[m].ui8_IS_Transition_Motion = 0 ;           //ui8 轴组是否在进行过渡运动*/

            AxesGroup_Mem[m].f32_Blending_Vel = 0;
            AxesGroup_Mem[m].ui8_TransitionIsAble = 0;
            AxesGroup_Mem[m].ui8_TransitionIsRun = 0;
            AxesGroup_Mem[m].ui8_TransitionIsAble = NO_TYPE;

            AxesGroup_Mem[m].ui8_Interrupt_Flag = 0;
            AxesGroup_Mem[m].ui8_Interrupt_Save_Infor = 0;
            AxesGroup_Mem[m].ui8_MotionFB_Num = 0;
            AxesGroup_Mem[m].ui64_MotionFB_Addr = 0;
            AxesGroup_Mem[m].ui8_Continue_Flag = 0;
        }
    }

// 1、遍历每一个valid有效的轴组， 初始化valid有效的轴组里的单轴的固定参数赋值，循环赋值，避免用户修改单轴参数和增删单轴
    int axis_n;
    //uint8_t Axis_Sum_In_Group[AXIS_MAXID_INGROUP];
    uint8_t Axis_Sum_In_Group[AXESGROUP_MAXNUM];
    for (int m = 0; m < AXESGROUP_MAXNUM; m++) {
        if(1 == AxesGroup_Mem[m].ui8_Valid)
        {
            //console_printf("-----------for1#--------\n");
            Axis_Sum_In_Group[m] = AxesGroup_Mem[m].ui8_Axis_Sum_In_Group;

            //对每个轴组里的单轴的固定参数赋值
            for (int n = 0; n < Axis_Sum_In_Group[m]; n++) {
                axis_n = AxesGroup_Mem[m].i16_Axis_Num_In_Group[n];//id =》实际单轴号
                if(axis_n == AXIS_IDLEID_INGROUP ) continue ; //轴号为-1，轴已经被移出或者未加入,2025-2-22赵建勇增加此行
                AxesGroup_Mem[m].f32_Joint_MaxVelocity[n] = *maxvel[axis_n];
                AxesGroup_Mem[m].f32_Joint_MaxAcceleration[n] = *maxacc[axis_n];
                AxesGroup_Mem[m].f32_Joint_MaxDeceleration[n] = *maxdec[axis_n];
                AxesGroup_Mem[m].f32_Joint_MaxJerk[n] = *maxjerk[axis_n];
                //回零homing部分直接读取单轴参数
            }

        }

    }

    /*2、轴组位置、速度变量的计算  第四个for循环
    double          f32_TCP_Target_Position[POSITION_SIZE];          **f32 当前轴组的下一个周期的目标位姿   X Y Z RX RY RZ || JA1 JA2....    初始值为0*
    double          f32_TCP_Last_Target_Position[POSITION_SIZE];         **f32 当前轴组的上一个周期的目标位姿   X Y Z RX RY RZ || JA1 JA2....    初始值为0*
    double          f32_TCP_Last_Last_Target_Position[POSITION_SIZE];         **f32 当前轴组上上一个周期的的目标位姿   X Y Z RX RY RZ初始值为0*
//只保存轴组 TCP 在 MCS 中的位置，速度，加速度；单轴的 ACS 运动信息会保存在单轴中
	double          f32_Now_TCP_Position[POSITION_SIZE] ;           **f32 当前轴组所处的位姿   需要读取单轴的位置进行计算  不一定为0*
	float          f32_Now_TCP_Velocity ;           **f32 当前轴组的速度   TCP_V  都是非负数  初始值为0*
	float          f32_Now_TCP_Acceleration ;           **f32 当前轴组的加速度   TCP_A || JA1 JA2...    初始值为0*
	uint8_t    ui8_ConstantVelocity;//是否在匀速运动
    uint8_t    ui8_Accelerating;//是否在加速
    uint8_t    ui8_Decelerating;//是否在减速
    uint8_t    ui8_InPosition;///是否到达目标位置  运动开始前置1，结束置0*/
    // 2、遍历每一个valid有效的轴组，计算当前位置，速度，加速度，以及一些变量的更新 (只写了PTP运动的目标位置计算）

    double MCS_X;
    double MCS_Y;
    double MCS_Z;
    double MCS_RX;
    double MCS_RY;
    double MCS_RZ;
    double temp2, temp1,temp_x,temp_y,temp_z,temp_rx,temp_ry,temp_rz;
    int temp3;//临时变量，不保存数据
    double temp_arr1[3];//临时变量，不保存数据
    for (int m = 0; m < AXESGROUP_MAXNUM; m++) {

        if(1 == AxesGroup_Mem[m].ui8_Valid && 1 == AxesGroup_Mem[m].ui8_Axesgroup_Init_Finish)
        {
            //console_printf("-----------for2#--------\n");
            //轴组当前位置: 每个轴的实际位置（*now_position[m]脉冲）=》角度 =》MCS的位姿
            double axis_now_angle[AXIS_SUM_INGROUP_MAX];
            for (int id = 0; id < Axis_Sum_In_Group[m]; id++) {
                axis_n = AxesGroup_Mem[m].i16_Axis_Num_In_Group[id];//id =》实际单轴号
                //axis_now_angle[id] = (*now_position[axis_n] - AxesGroup_Mem[m].i32_JointOffsets[id]) *
                //                     (AxesGroup_Mem[m].i8_JointDirections[id]) /
                //                     (AxesGroup_Mem[m].d64_JointGearRatios[id]);
                axis_now_angle[id] = (*last_target_position[axis_n] + *relative_position[axis_n] - AxesGroup_Mem[m].i32_JointOffsets[id]) *
                                     (AxesGroup_Mem[m].i8_JointDirections[id]) /
                                     (AxesGroup_Mem[m].d64_JointGearRatios[id]);



                //ARM987_actualJointAngles[1] := ARM987_jointDirections[1] * (ARM987_axis_array[1] - ARM987_jointOffsets[1]) / ARM987_gearRatios[1];
            }

            u8 Error;
            u16 ErrorID;
            ACS_MCS_KinTransform(Task,FBIndex,AxesGroup_Mem[m].ui8_Kin_Transform, 1, axis_now_angle, &MCS_X, &MCS_Y, &MCS_Z, &MCS_RX, &MCS_RY,
                                 &MCS_RZ, AxesGroup_Mem[m].f32_JointLimits, NULL, &Error, &ErrorID, AxesGroup_Mem[m].f32_DenHartA,
                                 AxesGroup_Mem[m].f32_DenHartD);
            /*uint8_t axesgroup_kin,//选择运动学模型
            uint8_t Forward, //选择正逆解：1正解；0逆解*/


            AxesGroup_Mem[m].f32_Now_TCP_Position[0] = MCS_X;
            AxesGroup_Mem[m].f32_Now_TCP_Position[1] = MCS_Y;
            AxesGroup_Mem[m].f32_Now_TCP_Position[2] = MCS_Z;
            AxesGroup_Mem[m].f32_Now_TCP_Position[3] = MCS_RX;
            AxesGroup_Mem[m].f32_Now_TCP_Position[4] = MCS_RY;
            AxesGroup_Mem[m].f32_Now_TCP_Position[5] = MCS_RZ;

            //轴组目标位置 target_position last_target_position
            //此时，只能通过单轴的目标位置 =》轴组的目标位置 每个轴的目标位置（*now_position[j]脉冲）=》角度 =》MCS的位姿
            //double axis_now_angle[AXIS_SUM_INGROUP_MAX];
            for (int id = 0; id < Axis_Sum_In_Group[m]; id++) {
                axis_n = AxesGroup_Mem[m].i16_Axis_Num_In_Group[id];//id =》实际单轴号
                axis_now_angle[id] = (*target_position[axis_n] + *relative_position[axis_n] - AxesGroup_Mem[m].i32_JointOffsets[id]) *
                                     (AxesGroup_Mem[m].i8_JointDirections[id]) /
                                     (AxesGroup_Mem[m].d64_JointGearRatios[id]);
                //ARM987_actualJointAngles[1] := ARM987_jointDirections[1] * (ARM987_axis_array[1] - ARM987_jointOffsets[1]) / ARM987_gearRatios[1];

            }

            ACS_MCS_KinTransform(Task,FBIndex,AxesGroup_Mem[m].ui8_Kin_Transform, 1, axis_now_angle, &MCS_X, &MCS_Y, &MCS_Z, &MCS_RX, &MCS_RY,
                                 &MCS_RZ, AxesGroup_Mem[m].f32_JointLimits, 0, &Error, &ErrorID, AxesGroup_Mem[m].f32_DenHartA,
                                 AxesGroup_Mem[m].f32_DenHartD);
            /*uint8_t axesgroup_kin,//选择运动学模型
            uint8_t Forward, //选择正逆解：1正解；0逆解*/

            AxesGroup_Mem[m].f32_TCP_Target_Position[0] = MCS_X;
            AxesGroup_Mem[m].f32_TCP_Target_Position[1] = MCS_Y;
            AxesGroup_Mem[m].f32_TCP_Target_Position[2] = MCS_Z;
            AxesGroup_Mem[m].f32_TCP_Target_Position[3] = MCS_RX;
            AxesGroup_Mem[m].f32_TCP_Target_Position[4] = MCS_RY;
            AxesGroup_Mem[m].f32_TCP_Target_Position[5] = MCS_RZ;

            //轴组当前的运动方向和运动速度: targetpostion - last_targetposition
            temp2 = 0.0;
            for(int i = 0; i< 3 ; i++)
            {
                AxesGroup_Mem[m].f32_Now_TCP_Direction_Distance[i] = AxesGroup_Mem[m].f32_TCP_Target_Position[i] - AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i];
                temp2+=AxesGroup_Mem[m].f32_Now_TCP_Direction_Distance[i]*AxesGroup_Mem[m].f32_Now_TCP_Direction_Distance[i];
            }
            AxesGroup_Mem[m].f32_Now_TCP_Velocity = sqrt(temp2);//每周期的运动距离

            //当前轴组的加速度
            temp1 = 0.0;
            temp3 = 1;
            for(int i = 0; i< 3 ; i++)
            {
                temp_arr1[i] = AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i] - AxesGroup_Mem[m].f32_TCP_Last_Last_Target_Position[i];
                temp1+=temp_arr1[i]*temp_arr1[i];
                if((temp_arr1[i] > 0 && AxesGroup_Mem[m].f32_Now_TCP_Direction_Distance[i] < 0)||(temp_arr1[i] < 0 && AxesGroup_Mem[m].f32_Now_TCP_Direction_Distance[i] > 0))
                {
                    temp3 = 0;//前后运动方向不一致
                }
            }
            if(1 == temp3)//方向相同
            {
                AxesGroup_Mem[m].f32_Now_TCP_Acceleration = AxesGroup_Mem[m].f32_Now_TCP_Velocity - sqrt(temp1);
            }
            else
            {
                AxesGroup_Mem[m].f32_Now_TCP_Acceleration = AxesGroup_Mem[m].f32_Now_TCP_Velocity + sqrt(temp1);
            }

            //部分变量更新  这个for循环每个周期开始都会执行一次
            if(temp2 == temp1 && temp2 > (min_vel_mm * min_vel_mm))
            {
                AxesGroup_Mem[m].ui8_ConstantVelocity = 1;//是否在匀速运动
                AxesGroup_Mem[m].ui8_Accelerating = 0;//是否在加速
                AxesGroup_Mem[m].ui8_Decelerating = 0;//是否在减速
            }
            else
            {
                AxesGroup_Mem[m].ui8_ConstantVelocity = 0;
                if(1 == temp3 && AxesGroup_Mem[m].f32_Now_TCP_Acceleration > 0)
                {
                    AxesGroup_Mem[m].ui8_Accelerating = 1;//是否在加速
                    AxesGroup_Mem[m].ui8_Decelerating = 0;//是否在减速
                }
                else if(1 == temp3 && AxesGroup_Mem[m].f32_Now_TCP_Acceleration < 0)
                {
                    AxesGroup_Mem[m].ui8_Accelerating = 0;//是否在加速
                    AxesGroup_Mem[m].ui8_Decelerating = 1;//是否在减速
                }
                else if(0 == temp3)//当前运动和上一周期运动反向 =》加速
                {
                    AxesGroup_Mem[m].ui8_Accelerating = 1;//是否在加速
                    AxesGroup_Mem[m].ui8_Decelerating = 0;//是否在减速
                }
                else{}

            }

            temp_x = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[0] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[0]);
            temp_y = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[1] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[1]);
            temp_z = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[2] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[2]);
            temp_rx = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[3] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[3]);
            temp_ry = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[4] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[4]);
            temp_rz = fabs(AxesGroup_Mem[m].f32_Now_TCP_Position[5] - AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[5]);

            //当前位置在运动目标位置窗口值范围内，并且停留一段时间，都算到目标位置了（运动目标位置：整个运动（存在前后功能块混承）结束的位置，到达该位置后速度为0）
            //20221119：目前运动只考虑当前功能块运动位置，并不是整个运动位置；因此不考虑时间窗口值，等待后续优化
            if(temp_x < min_pos_mm && temp_y < min_pos_mm && temp_z < min_pos_mm && temp_rx < min_pos_angle && temp_ry < min_pos_angle && temp_rz < min_pos_angle)
            {
                AxesGroup_Mem[m].ui8_InPosition = 1;///是否到达目标位置  运动开始前置1，结束置0*/
            }
            else
            {
                AxesGroup_Mem[m].ui8_InPosition = 0;///是否到达目标位置  运动开始前置1，结束置0*/
            }

            for(int i = 0; i< POSITION_SIZE ; i++)
            {
                AxesGroup_Mem[m].f32_TCP_Last_Last_Target_Position[i] = AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i];
                AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i] = AxesGroup_Mem[m].f32_TCP_Target_Position[i];

            }
            AxesGroup_Mem[m].ui8_AxesGroup_Run_Next = 0;

        }

    }

    /*3、轴组状态的自动转换   第五个for循环
    1）轴组停止运动=》进入GroupStandby状态 （需要判断是不是把Velfactor设置为了0，如果是则不进入静止状态）
    2）复位完成后=》errorstop变成disable（在MC_AxesReset里实现了）
    3）单轴错误errorstop =》轴组 errorstop
    4）废弃 放在cass平台里检查 默认用户肯定能设置对轴组（轴组内单轴数量 ！= 轴组绑定的运动学模型规定的轴组数量 =》轴组 errorstop
    5）轴组速度、加速度、减速度超限 =》轴组 errorstop
     6)AxesGroup_Mem[m].ui8_ConstantVelocity = 0;//是否在匀速运动
                AxesGroup_Mem[m].ui8_Accelerating = 0;//是否在加速
                AxesGroup_Mem[m].ui8_Decelerating = 0;//是否在减速
    */
    //3、遍历每一个valid有效的轴组，轴组状态的自动转换
    uint16_t grouperror;
    for(int m = 0; m < AXESGROUP_MAXNUM;m++)
    {

        if(1 == AxesGroup_Mem[m].ui8_Valid && 1 == AxesGroup_Mem[m].ui8_Axesgroup_Init_Finish)
        {
            //console_printf("-----------for3#--------\n");
            grouperror = 0;
            if(1 == AxesGroup_Mem[m].ui8_AxesGroup_Reset_Flag)
            {//当前在进行轴组复位操作 目前不需要操作
                //这里是进行smallsystem里的轴组参数的复位(FB_MCAxesGroupReset无法访问的参数）；FB_MCAxesGroupReset可以访问的参数在FB_MCAxesGroupReset里复位

            }
            else
            {//当前轴组复位完成，或不在进行复位操作
                //发生异常，轴组进入 MC_GroupErrorstop 状态
                for (int id = 0; id < Axis_Sum_In_Group[m]; id++)
                {
                    axis_n = AxesGroup_Mem[m].i16_Axis_Num_In_Group[id];//id =》实际单轴号
                    if(axis_n == AXIS_IDLEID_INGROUP ) continue ; //轴号为-1，轴已经被移出或者未加入,2025-2-22赵建勇增加此行
                    //单轴错误  保证一次只输出一种错误的单轴id 防止i16_ErrorAxisID[id]被覆盖
                    if((0 == grouperror || AxisState_Errorstop_Error == grouperror) && MC_Errorstop == *state[axis_n])
                    {
                        AxesGroup_Mem[m].ui8_Axesgroup_GroupError = 1;
                        AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupErrorstop;
                        AxesGroup_Mem[m].ui16_Axesgroup_GroupErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + AxisState_Errorstop_Error;
                        AxesGroup_Mem[m].i16_ErrorAxisID[id] = id;
                        grouperror = AxisState_Errorstop_Error;
                        //break;
                    }else{}
                    //速度超限
                    if((0 == grouperror || AxisVel_ExceedLimit_Error == grouperror) && *maxvel[axis_n] < (*now_velocity[axis_n]*1000.0))
                    {
                        //暂时先报errorid，当个warning处理，不会直接停止运动
                        //AxesGroup_Mem[m].ui8_Axesgroup_GroupError = 1;
                        //AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupErrorstop;
                        AxesGroup_Mem[m].ui16_Axesgroup_GroupErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + AxisVel_ExceedLimit_Error;
                        AxesGroup_Mem[m].i16_ErrorAxisID[id] = id;
                        grouperror = AxisVel_ExceedLimit_Error;
                    }else{}
                    /*加速度超限  需要修改单轴的轴参数，暂缓添加该功能
                    if((0 == grouperror || AxisAcc_ExceedLimit_Error == grouperror) && *maxacc[axis_n] < *now_velocity[axis_n])
                    {
                        AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupErrorstop;
                        AxesGroup_Mem[m].ui16_Axesgroup_GroupErrorID = AxisAcc_ExceedLimit_Error;
                        AxesGroup_Mem[m].ErrorAxisID[id] = id;
                        grouperror = AxisAcc_ExceedLimit_Error;
                    }else{}
                    //减速度超限
                    if((0 == grouperror || Vel_ExceedLimit_Error == grouperror) && *maxvel[axis_n] < *now_velocity[axis_n])
                    {
                        AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupErrorstop;
                        AxesGroup_Mem[m].ui16_Axesgroup_GroupErrorID = Vel_ExceedLimit_Error;
                        AxesGroup_Mem[m].ErrorAxisID[id] = id;
                        grouperror = Vel_ExceedLimit_Error;
                    }else{}*/
                }

                //如果没有轴组错误，进行状态自动切换
                if(AxesGroup_Mem[m].ui8_AxesGroup_State != MC_GroupErrorstop)
                {
                    //1）轴组停止运动=》进入GroupStandby状态 （需要判断是不是把 Velfactor 设置为了0，如果是则不进入静止状态）
                    //2022.11.21：此处只实现了位置模式的控制，后续可以再进行添加
                    temp_x = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[0] - AxesGroup_Mem[m].f32_Now_TCP_Position[0]);
                    temp_y = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[1] - AxesGroup_Mem[m].f32_Now_TCP_Position[1]);
                    temp_z = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[2] - AxesGroup_Mem[m].f32_Now_TCP_Position[2]);
                    temp_rx = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[3] - AxesGroup_Mem[m].f32_Now_TCP_Position[3]);
                    temp_ry = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[4] - AxesGroup_Mem[m].f32_Now_TCP_Position[4]);
                    temp_rz = fabs(AxesGroup_Mem[m].f32_TCP_Target_Position[5] - AxesGroup_Mem[m].f32_Now_TCP_Position[5]);
                    //if(temp_x < min_pos_mm && temp_y < min_pos_mm && temp_z < min_pos_mm)
                     //   console_printf("\n GroupStateCheck: temp_x=%lf,y=%lf,z=%lf,rx=%lf,ry=%lf,rz=%lf,state=%d,busy=%d\n",temp_x,temp_y,temp_z,temp_rx,temp_ry,temp_rz,AxesGroup_Mem[m].ui8_AxesGroup_State,AxesGroup_Mem[m].ui8_AxesGroup_Busy);
                    //当前位置在运动目标位置窗口值范围内，并且停留一段时间，都算到目标位置了（运动目标位置：整个运动（存在前后功能块混承）结束的位置，到达该位置后速度为0）
                    //20221119：目前运动只考虑当前功能块运动位置，并不是整个运动位置；因此不考虑时间窗口值，等待后续优化
                    if(temp_x < min_pos_mm && temp_y < min_pos_mm && temp_z < min_pos_mm && temp_rx < min_pos_angle && temp_ry < min_pos_angle && temp_rz < min_pos_angle
                       && AxesGroup_Mem[m].ui8_AxesGroup_State != MC_GroupDisabled && AxesGroup_Mem[m].ui8_AxesGroup_State != MC_GroupStopping
                       && 0 == AxesGroup_Mem[m].ui8_AxesGroup_Busy )//&& AxesGroup_Mem[m].f32_VelFactor > 0)只需要考虑轴组是否在busy就行，不用考虑f32_VelFactor
                    {
                        AxesGroup_Mem[m].ui8_AxesGroup_State = MC_GroupStandby;
                        AxesGroup_Mem[m].ui8_ConstantVelocity = 0;//是否在匀速运动
                        AxesGroup_Mem[m].ui8_Accelerating = 0;//是否在加速
                        AxesGroup_Mem[m].ui8_Decelerating = 0;//是否在减速
                        for(int i = 0; i< POSITION_SIZE ; i++)
                        {
                            AxesGroup_Mem[m].f32_Now_TCP_Motion_Aimpos[i] = AxesGroup_Mem[m].f32_Now_TCP_Position[i];
                            AxesGroup_Mem[m].f32_TCP_Last_Last_Target_Position[i] = AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i];
                            AxesGroup_Mem[m].f32_TCP_Last_Target_Position[i] = AxesGroup_Mem[m].f32_TCP_Target_Position[i];
                            AxesGroup_Mem[m].f32_TCP_Target_Position[i] = AxesGroup_Mem[m].f32_Now_TCP_Position[i];

                        }
                    }else{}


                }

            }

        }


    }
    #endif
#endif

}

FBDTON(ePLCKernalSta *Task, Uint32 FBIndex,struct TON *FB){


/*Separator--*--Separator--*--Separator*/
//
        if ( FB->IN == 0)
        {
        FB->Q =0;
        FB->ET = 0 ;
        FB->usCnt = 0;
        }
        else if ( FB->IN !=0 )
        {
            //2022-02-03 modified for task period less than 1ms
            if (FB->PET > FB->ET ) //计数值
            {
                FB->usCnt  += Task->taskPeriod;  //time elapsed us
                while ( FB->usCnt >= 1000)  //n*1ms arrived
                {
                   FB->ET += 1;  //计数值没到才加
                   FB->usCnt -= 1000;
                }

            }

            if (FB->PET <= FB->ET ) //计数值
            {
                FB->Q =1 ;

            }
        }
        //保存上一次状态
        FB->INLast = FB->IN ;
}

FBDAND3(ePLCKernalSta *Task, Uint32 FBIndex,Uint8 *OUT1, Uint8 OUT1n,Uint8 IN1, Uint8 IN1n,Uint8 IN2, Uint8 IN2n,Uint8 IN3, Uint8 IN3n){if((IN1 & (1<<IN1n)) && (IN2 & (1<<IN2n)) && (IN3 & (1<<IN3n)))
*OUT1 |= (1 << OUT1n);
else
*OUT1 &=~ (1 << OUT1n);
}

FBDAND3(ePLCKernalSta *Task, Uint32 FBIndex,Uint8 *OUT1, Uint8 OUT1n,Uint8 IN1, Uint8 IN1n,Uint8 IN2, Uint8 IN2n,Uint8 IN3, Uint8 IN3n){if((IN1 & (1<<IN1n)) && (IN2 & (1<<IN2n)) && (IN3 & (1<<IN3n)))
*OUT1 |= (1 << OUT1n);
else
*OUT1 &=~ (1 << OUT1n);
}

FBDMC_MoveDirectAbsolute(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_MoveDirectAbsolute *FB){

/*Separator--*--Separator--*--Separator*/
//MC_MoveDirectAbsolute
//2023/3/11第一次修改：1、删去S形初速度为0的强行求解acc，dec算法；2、TMNone-Abort模式后续打断功能块更改为 MC_Halt
/*Version1.0：1、调整最大速度保证各轴同时到达，加减速时间段不一致；2、过渡不经过过渡点；
 * 3、单轴当前位置改为LAST_TARGET_POSITION(为了配合单轴功能块FBDMC_MoveAbsolute）4、单轴运动超过一定的时间强行完成*/

/*20230716 Version1.2：1、过渡速度太大，运动距离太短不混成*/

/*20230713-Version1.1：修改，halt启动，只能打断正在进行的运动，无法打断在buffer区的运动，halt完成后会继续运动(*axesgroup_now_motion_type == HALTING_M)*/


#ifndef _CASS_PRECOMPILE_
    struct MoveDirectAbsolute_MidArray * mid_arr;//切记！每一次用之前都要赋值：mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;

    uint8_t *axis_state;
    struct AXESGROUP * axesgroup = &AxesGroup_Mem[FB->AxesGroup];
    uint8_t *axesgroup_state = (uint8_t*)(&axesgroup->ui8_AxesGroup_State);

    double *axesgroup_PCS_relative_pos = (axesgroup->f32_PCS_Relative_position);         /**f32 PCS和实际原点的相对偏移量  MCS PCS: 三个位置量+3个姿态（方向）量  -- X Y Z RX RY RZ */
    double *axesgroup_MCS_relative_pos = (axesgroup->f32_MCS_Relative_position);        /**f32 MCS和实际原点的相对偏移量*/
    double *axesgroup_ACS_relative_pos = (axesgroup->f32_ACS_Relative_position);  /**f32 ACS和实际原点的相对偏移量 ACS: 轴组内所有轴的角度*/

    uint8_t *axesgroup_buffermode = (uint8_t*)(&axesgroup->ui8_BufferMode);
    uint8_t *axesgroup_transitionmode = (uint8_t*)(&axesgroup->ui8_TransitionMode);
    float *axesgroup_transitionparameter = (&axesgroup->f32_TransitionParameter);

    uint8_t *axesgroup_now_motion_type = (&axesgroup->ui8_Now_Motion_Type);
    uint8_t *axesgroup_buffer_motion_type =(&axesgroup->ui8_Buffer_Motion_Type);
    uint8_t *axesgroup_is_transition_motion = (&axesgroup->ui8_IS_Transition_Motion) ;           /**ui8 轴组是否在进行过渡运动*/


    uint8_t     *axesgroup_busy =(&axesgroup->ui8_AxesGroup_Busy );         /**ui8 当前轴组忙碌标志 */
    uint8_t     *axesgroup_buffer_busy = (&axesgroup->ui8_AxesGroup_Buffer_Busy);     /**ui8  轴组的缓冲区是否繁忙*/

    double     *axesgroup_last_last_target_position = (axesgroup->f32_TCP_Last_Last_Target_Position);     /**ui8  轴组上上个周期的目标位姿*/
    double     *axesgroup_last_target_position = (axesgroup->f32_TCP_Last_Target_Position);     /**ui8  轴组上个周期的目标位姿*/
//    double     *axesgroup_target_position = (axesgroup->f32_TCP_Target_Position);     /**ui8  轴组上个周期的目标位姿*/

    uint8_t     *axesgroup_run_number =(&axesgroup->ui8_AxesGroup_Run_Number);     /**ui8  轴组的缓冲区是否繁忙*/
    uint8_t     *run_next = (&axesgroup->ui8_AxesGroup_Run_Next);       /*ui8 当前FB运行完成置1，每个周期开始的时候都会被置0 */

    float* axesgroup_now_tcp_vel =(&axesgroup->f32_Now_TCP_Velocity) ;
    double* axesgroup_now_tcp_motion_aimpos = (axesgroup->f32_Now_TCP_Motion_Aimpos);    /**f32 当前轴组运动的目标位姿   X Y Z RX RY RZ || JA1 JA2...  */
    float* axesgroup_now_tcp_motion_vel = (&axesgroup->f32_Now_TCP_Motion_Velocity);    /**f32 当前轴组运动的目标速度    TCP_V || JV1 JV2...   */
    double* axesgroup_now_tcp_motion_direction =(axesgroup->f32_Now_TCP_Motion_Direction_Distance);    /**f32 当前轴组运动的目标方向，是一个向量  */

    double* axesgroup_PCStoMCS_TM = (axesgroup->d64_PCStoMCS_TM)	;         /**f32 PCS->MCS的变换矩阵T 4*4 */
    int16_t *axis_num_ingroup = (axesgroup->i16_Axis_Num_In_Group);
    uint8_t *axis_sum_ingroup = (&axesgroup->ui8_Axis_Sum_In_Group);
//    double* axesgroup_joint_limits = (axesgroup->f32_JointLimits);  /*f32  该轴组绑定的运动学模型（机器人）每个轴的角度限制*/  //机器人固定参数  用户不可自定义
    int8_t* axesgroup_joint_directions = (axesgroup->i8_JointDirections);  /*i8  该轴组绑定的运动学模型（机器人）每个轴的电机旋转方向  顺时针或者逆时针 默认为1--顺时针旋转2--逆时针旋转 */  //开放给用户自定义
    double* axesgroup_joint_ratios = (axesgroup->d64_JointGearRatios); /*i32 该轴组绑定的运动学模型（机器人）的每个轴的齿轮比*/       //开放给用户自定义
    int32_t* axesgroup_joint_offsets =(axesgroup->i32_JointOffsets);//偏移量=（控制器读取到的）电子零点-机械当前位置

    uint8_t* axesgroup_axis_able_blending = (axesgroup->ui8_Axis_Able_blending);
    double* axesgroup_axis_aimpulse = (axesgroup->f32_Now_Axis_Motion_AimPulse);

    uint64_t* motionFB_addr = (&axesgroup->ui64_MotionFB_Addr);
    uint8_t *inter_flag = (&axesgroup->ui8_Interrupt_Flag);
    uint8_t *inter_save = (&axesgroup->ui8_Interrupt_Save_Infor);
    uint8_t *motionFB_num = (&axesgroup->ui8_MotionFB_Num);//运动功能块编号1-255

    uint8_t *Axesgroup_GroupError = (&axesgroup->ui8_Axesgroup_GroupError);
    uint16_t *Axesgroup_GroupErrorID =(&axesgroup->ui16_Axesgroup_GroupErrorID);//运动功能块编号1-255

    double axis_last_target_position[AXIS_SUM_INGROUP_MAX];
    int32_t *now_axis_direction_p[AXIS_SUM_INGROUP_MAX];
    double* axis_last_target_position_p;
    double axis_last_target_angle[AXIS_SUM_INGROUP_MAX];

    uint8_t  error_flag = 0;
    int tm_num;
    double ACS_pos[AXIS_SUM_INGROUP_MAX];
    double PCS_pos[4];
    double PCStoMCS_TM[4][4];
    double ACS_aimpos[AXIS_SUM_INGROUP_MAX];

    uint8_t ACS_MCS_KinTrans_error;//输出量，求逆解的时候有，求正解时不需要
    uint16_t ACS_MCS_KinTrans_errorID;//输出量，求逆解的时候有，求正解时不需要

    double aim_pulse_distance[AXIS_SUM_INGROUP_MAX];

    double axis_finish_time[AXIS_SUM_INGROUP_MAX];

    double axis_max_v1[AXIS_SUM_INGROUP_MAX];//不规定时间，完成运动可以达到的最大速度
    double axis_max_v2[AXIS_SUM_INGROUP_MAX];// 在规定时间 FB->max_finish_time ，可以达到的最大速度
    double *axis_relative_position_p ;
    float deviation_t;

    deviation_t = 1.0;  //偏差的最小可接受周期数

    int axis_n;
    float* axis_now_velocity_p, axis_now_velocity;
    int axis_now_direction[AXIS_SUM_INGROUP_MAX];
    int axis_dec_sum;

    //轴组运动中，出现功能块error或者进入MC_GroupErrorstop状态，后续功能块全部初始化，不再继续运动
    if(1 == *Axesgroup_GroupError)
    {
        if(FB->run_flag || FB->TM_run_flag)
        {
            FB->CommandAborted = true;
            FB->Active = false;
            FB->Busy = false;
            FB->Done = false;
        }
        FB->exe = false;
        FB->run = false;
        FB->run_flag = false;
        FB->buffer = false;
        FB->buffer_run = false;
        FB->TM_run_flag = false;
        FB->buffer = false;
        *axesgroup_busy = 0;
        *axesgroup_buffer_busy = 0;
    }

    //当前任务被异常状态中断
    if((*axesgroup_now_motion_type == HALTING_M || *axesgroup_state == MC_GroupDisabled || *axesgroup_state == MC_GroupErrorstop || *axesgroup_state == MC_GroupStopping) && (FB->run_flag || FB->exe || FB->run || FB->TM_run_flag))
    {

        FB->CommandAborted = true;
        FB->Active = false;
        FB->exe = false;
        FB->run = false;
        FB->run_flag = false;
        FB->buffer = false;
        FB->buffer_run = false;
        FB->TM_run_flag = false;
        FB->run_numberF = 0;
    }

    //该模块不在使用  （不是上跳沿，不在执行运动任务，也不在缓冲区 （一个周期内：buffer结束后--run为true，进行计算--runflag为true）
    if(!FB->Execute && !FB->run_flag && !FB->buffer && !FB->TM_run_flag)
    {
        if(*Axesgroup_GroupError == 0)
        {
            FB->Error = false;
        }
        if(FB->Error == false)
        {//为了处理warning
            FB->ErrorID = 0;
        }
        FB->Done = false;
        FB->Active = false;
        FB->CommandAborted = false;
        FB->run_numberF = 0;
        FB->move_state = 0;
        FB->tm_mode = 0;
        FB->run_flag = false;
        FB->buffer_run = false;
        FB->TM_run_flag = false;
        FB->exe = false;
        FB->run = false;
        FB->execute_before = false;
    }


/**    当前模块正在执行时,buffer区存在缓存的模块,执行一次计算    下一个模块的混承决定的是当前模块过渡曲线的初速度*/
    if(FB->run_flag && *axesgroup_buffer_busy == 1 && !FB->buffer_run && FB->Done != true && FB->CommandAborted != true)//计算完FB->buffer_run变为true，只计算一次，不会进行重复计算
    {
        mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;

        if(*axesgroup_transitionmode == TMNone)
        {
            FB->buffer_run = true;
           // console_printf("\n -------- FB->buffer_run = true; -------------------\n");
            //不同过渡模式和混承模式
            if(*axesgroup_buffermode == Buffered){
                //无需过渡
                FB->TM_run_flag = false;
                FB->run_flag = true;
            }
            else if(*axesgroup_buffermode == Aborting)
            {
                if(HALTING_M == *axesgroup_buffer_motion_type)
                {
                    //当前运动直接被打断
                }
                else
                {
                    FB->tm_mode = 1;

                    FB->TM_run_flag = true;
                    FB->run_flag = false;
                    FB->exe = false;
                    FB->run = false;
                }
            }else{}
        }
        else if(*axesgroup_transitionmode == TMConstantVelocity) {

            //blending模式 2 3 4 5
            if (*axesgroup_buffermode != Aborting) {
                if (PTP == *axesgroup_buffer_motion_type)
                {
                    int no_blending = 1;
                    if(1 == FB->move_state)
                    {
                        FB->tm_mode = 2;
                        for(int id1 = 0; id1 < *axis_sum_ingroup;id1++)
                        {
                            if(1 == axesgroup_axis_able_blending[id1])
                            {
                                //启动contiousabs 进行过渡
                                //需要给出endvel = Velocity = TP * mid_arr->axis_max_vel position不变
                                axis_n = axis_num_ingroup[id1];
                                axis_now_velocity_p = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + NOW_VELOCITY]);
                                axis_now_velocity = fabs(*axis_now_velocity_p);
                                no_blending = 0;
                                mid_arr->axis_max_vel[id1] = mid_arr->axis_max_vel[id1] * (*axesgroup_transitionparameter);
                                if (axis_now_velocity < mid_arr->axis_max_vel[id1])
                                {
                                    mid_arr->axis_max_vel[id1] = axis_now_velocity;
                                }
                            }
                        }
                        if(1 == no_blending)
                        {
                            FB->buffer_run = true;
                           // console_printf("\n--------------if(1 == no_blending)------########333-----------------------------------------------\n");
                            FB->TM_run_flag = false;
                            FB->run_flag = true;
                            FB->exe = false;
                            FB->run = false;
                        }
                        else
                        {
                            FB->buffer_run = true;
                           // console_printf("\n--------------if(0 == no_blending)------########333---------------------------------------------------\n");
                            FB->TM_run_flag = true;
                            FB->run_flag = true;//可以混承的功能块被打断，不可以混承的继续运动
                            FB->exe = false;
                            FB->run = false;
                        }
                    }



                }
            }
            else if (*axesgroup_buffermode == Aborting) {
                FB->buffer_run = true;
                //当前运动直接被打断
            }
        }


        //和直线运动混承
        //和圆弧混承
    }


//启动功能块       功能块在运动过程中，不可以通过重置execute来重新启动
    if( FB->run_flag == false && FB->TM_run_flag == false &&FB->Execute && (!FB->execute_before))
    {
        //console_printf("\n ---------MC_MoveDirectAbsolute-----------------------------------\n");

        if(1 == *Axesgroup_GroupError)
        {//这个错误相当于一种warning，所以FB->Error为false，提醒用户前面存在error的运动功能块，需要把前面的功能块error消除
            FB->Error = false;
            FB->ErrorID = AXESGROUP_MOTION_FB_WARNING;
        }
        else
        {
            if(*axesgroup_state != MC_GroupMoving && *axesgroup_state != MC_GroupStandby)
            {
                FB->Error = true;
                FB->ErrorID = StateError;
            }
            else
            {
                if(FB->AxesGroup >= AXESGROUP_MAXNUM || FB->AxesGroup < AXESGROUP_MINNUM)
                {
                    FB->Error = true;
                    FB->ErrorID = AxesGroupNum_ParameterError;
                }
                else
                {
                    //判断当前FB的运动 混承模式（轮廓速度）和过渡模式（轮廓形状）是否冲突
                    error_flag = 0;
                    switch(FB->TransitionMode)
                    {
                        case  TMNone://无过渡，初速度必须为0
                            if(FB->BufferMode == mcBlendingLow ||FB->BufferMode == mcBlendingPrevious || FB->BufferMode == mcBlendingNext || FB->BufferMode == mcBlendingHigh )
                            {
                                error_flag = 1;
                            }
                            break;
                        case  TMConstantVelocity://有过渡，初速度不能为0
                            if(FB->BufferMode == mcBuffered )
                            {
                                error_flag = 1;
                            }
                            break;
                        default:
                            error_flag = 1;
                    }

                    if(error_flag == 1)
                    {
                        FB->Error = true;
                        FB->ErrorID = TransitionMode_ParameterError;
                        FB->Busy = false;
                    }
                    else
                    {
                        //JERK可以为0，速度和加速度不行
                        if(FB->VelFactor <= 0 || FB->VelFactor > 1 ||FB->AccFactor <= 0 || FB->AccFactor > 1 ||FB->JerkFactor < 0 || FB->JerkFactor > 1 )
                        {
                            FB->Error = true;
                            FB->ErrorID = ParameterError;
                            FB->Busy = false;
                        }
                        else
                        {
                            if( FB->CoordSystem !=MCS && FB->CoordSystem != ACS && FB->CoordSystem !=   PCS)
                            {
                                FB->Error = true;
                                FB->ErrorID = CoordSystem_ParameterError;
                            }
                            else
                            {
                                FB->Error = false;
                                FB->ErrorID = NoError;
                                FB->Busy = true;
                            }

                        }

                    }

                }

            }

            if(!FB->Error)
            {
                if(FB->MidArray_Addr == 0)
                {
                    FB->MidArray_Addr = (uint64_t) malloc(sizeof(struct MoveDirectAbsolute_MidArray));
                }

                if(FB->MidArray_Addr != 0) {
                    memset((void *)FB->MidArray_Addr, 0, sizeof(struct MoveDirectAbsolute_MidArray));
                    mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;
                    for(int temp = 0; temp <AXIS_MAXID_INGROUP;temp++ )
                    {
                        //功能块Execute=0，run_flag=0, buffer=0(如果有该成员），功能块才会处于不被使用状态，初始化成员
                        mid_arr->FB_MoveAbsolute[temp].Execute = 0 ;
                        mid_arr->FB_MoveAbsolute[temp].execute_before = 0 ;
                        mid_arr->FB_MoveAbsolute[temp].run_flag = 0 ;
                        mid_arr->FB_MoveAbsolute[temp].buffer = 0 ;
                        FBDMC_MoveAbsolute(Task, FBIndex, &mid_arr->FB_MoveAbsolute[temp]);

                        mid_arr->FB_TM_Halt[temp].Execute = 0 ;
                        mid_arr->FB_TM_Halt[temp].execute_before = 0 ;
                        mid_arr->FB_TM_Halt[temp].run_flag = 0 ;
                        mid_arr->FB_TM_Halt[temp].buffer = 0 ;
                        FBDMC_Halt(Task, FBIndex, &mid_arr->FB_TM_Halt[temp]);

                        mid_arr->FB_TM_MoveContiousAbsolute[temp].Execute = 0 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[temp].execute_before = 0 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[temp].run_flag = 0 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[temp].buffer = 0 ;
                        FBDMC_MoveContiousAbsolute(Task, FBIndex, &mid_arr->FB_TM_MoveContiousAbsolute[temp]);

                        mid_arr->FB_MC_MoveVelocity[temp].Execute = 0 ;
                        mid_arr->FB_MC_MoveVelocity[temp].execute_before = 0 ;
                        mid_arr->FB_MC_MoveVelocity[temp].run_flag = 0 ;
                        mid_arr->FB_MC_MoveVelocity[temp].buffer = 0 ;
                        FBDMC_MoveVelocity(Task, FBIndex, &mid_arr->FB_MC_MoveVelocity[temp]);
                        //moveVelocity时间初始化为0
                        mid_arr->MoveVel_time[temp] = 0;
                    }

                    ////单个轴的单位统一为：多少脉冲每周期
                    for(int n = 0 ; n < *axis_sum_ingroup; n++)
                    {
                        if(axis_num_ingroup[n]!= AXIS_IDLEID_INGROUP)
                        {
                            //单位为脉冲/ms
                            mid_arr->axis_should_motion[n] = 1;
                            mid_arr->every_axis_maxvel[n] =  axesgroup->f32_Joint_MaxVelocity[n] * FB->VelFactor/1000.0;
                            mid_arr->every_axis_maxacc[n] =  axesgroup->f32_Joint_MaxAcceleration[n] * FB->AccFactor/1000000.0;
                            mid_arr->every_axis_maxdec[n] =  axesgroup->f32_Joint_MaxDeceleration[n]  * FB->AccFactor/1000000.0;
                            mid_arr->every_axis_jerk[n] =  axesgroup->f32_Joint_MaxJerk[n] * FB->JerkFactor/1000000000.0;
                 //           console_printf("    mid_arr->every_axis_maxvel[%d] = %lf; mid_arr->every_axis_jerk[%d] = %lf, mid_arr->every_axis_maxacc[%d] = %lf\n",n,mid_arr->every_axis_maxvel[n],n,mid_arr->every_axis_jerk[n],n,mid_arr->every_axis_maxacc[n]);
                        }
                    }

                    //把其他坐标系的运动信息换算到MCS中
                    if(FB->CoordSystem == MCS)
                    {
                        //坐标量XYZ
                        for(int i = 0; i< 3; i++)
                        {
                            ////原来的坐标系的FB运动的目标位置=目标绝对位置 + 零点的相对偏移值（MC_GroupSetPosition设置该值，复位时为0）
                            //坐标系的零点是不会发生变化的
                            mid_arr->MCS_aimpos[i] = FB->Position[i] + axesgroup_MCS_relative_pos[i];
                            console_printf("FBDMC_MoveDirectAbsolute:MCS_aimpos[%d] = %lf\n",i,mid_arr->MCS_aimpos[i]);
                        }
                        //方向量RX,RY,RZ
                        for(int i = 3; i< POSITION_SIZE; i++)
                        {
                            mid_arr->MCS_aimpos[i] = FB->Position[i];
                            console_printf("FBDMC_MoveDirectAbsolute:MCS_aimpos[%d] = %lf\n",i,mid_arr->MCS_aimpos[i]);
                        }
                    }

                    else if(FB->CoordSystem == PCS)
                    {
                        for(int i = 0; i< 3; i++)
                        {
                            PCS_pos[i] = FB->Position[i] + axesgroup_PCS_relative_pos[i];
                        }
                        PCS_pos[3] = 1;

                        //PCS->MCS的转换矩阵
                        tm_num = 0;
                        for(int i=0;i<4;i++)
                        {
                            for(int j=0;j<4;j++)
                            {
                                PCStoMCS_TM[i][j] = axesgroup_PCStoMCS_TM[tm_num];
                                tm_num++;
                            }
                        }

                        //PCS的坐标转换到MCS下 mid_arr->MCS_aimpos =  PCStoMCS_TM*PCS_pos
                        //求出前三个坐标就可以 ,最后一行是1没有意义（[3][4]*[4][1])=[3][1])
                        for(int i = 0; i < 3; i++)
                        {
                            double sum = 0.0;
                            for(int m = 0; m < 4; m++)
                            {
                                sum = sum + PCStoMCS_TM[i][m] * PCS_pos[m];
                            }
                            mid_arr->MCS_aimpos[i] = sum;
                        }

                        ///假设MCS和PCS的X,Y,Z轴方向一致，即PCS不进行旋转；因此，PCS的方向量RX,RY,RZ和MCS中的一致
                        //方向量RX,RY,RZ
                        for(int i = 3; i< POSITION_SIZE; i++)
                        {
                            mid_arr->MCS_aimpos[i] = FB->Position[i];
                        }
                    }

                    else if(FB->CoordSystem == ACS)
                    {
                        ///ACS，求运动学正解
                        //首先，目标位置加上偏移量
                        for(int i = 0; i< *axis_sum_ingroup; i++)
                        {
                            ACS_pos[i] = FB->Position[i] + axesgroup_ACS_relative_pos[i];//（旧原点）实际的ACS位置 = 新原点的ACS位置+新原点-旧原点的偏差值
                        }
                        ACS_MCS_KinTransform(Task, FBIndex,axesgroup->ui8_Kin_Transform, 1, ACS_pos, &mid_arr->MCS_aimpos[0], &mid_arr->MCS_aimpos[1], &mid_arr->MCS_aimpos[2],&mid_arr->MCS_aimpos[3],&mid_arr->MCS_aimpos[4],
                                             &mid_arr->MCS_aimpos[5], axesgroup->f32_JointLimits, NULL,  &FB->Error_, &FB->ErrorID,axesgroup->f32_DenHartA, axesgroup->f32_DenHartD);

                    }else{}

                    //轴没有错误，可以开始执行
                    FB->exe = true;
                }
                else
                {
                    FB->Error = true;
                    FB->ErrorID = MallocFailError;
                    FB->Busy = false;
                    FB->exe = false;
                }

                FB->buffer = false;
                FB->run = false;
                FB->buffer_run = false;
                FB->run_flag = false;
                FB->TM_run_flag = false;
                FB->move_state = 0;
                FB->tm_mode = 0;

            }
        }


    }
    FB->execute_before = FB->Execute;

    // 当前FB混承信息传递给上个FB 处理当前FB和上个FB 的过渡和混承（轮廓(开始）速度）
    if(FB->exe)
    {
        mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;
        uint64_t fb_addr = (uint64_t)FB;
        ///不插入过渡曲线，上一个FB速度降为0，才开始当前FB运动
        ////buffered只能选择aborting 和 buffered；
        if(FB->TransitionMode == TMNone)
        {
            /*进入缓冲区*/
            if(*axesgroup_buffer_busy == 0)
            {
                FB->buffer = true;//FB处于buffer中，在缓冲区内

                *axesgroup_buffer_busy = 1;//轴组的buffer里存有FB
                //console_printf("\n ------ *axesgroup_buffer_busy == 0 -------------------\n");
                //缓冲区里的FB的混承模式和过渡模式信息
                *axesgroup_transitionmode = TMNone;
                *axesgroup_buffermode = FB->BufferMode ;
                *axesgroup_buffer_motion_type = PTP;

            }
            /*等前一个任务执行完成，也就是前一个FB运动速度降为0*/
            if( *axesgroup_busy == 0 && *run_next == 0 && ((FB->buffer &&*inter_flag != 1) ||(*inter_flag == 1 && fb_addr == *motionFB_addr)))//每个周期开始都会被smallsystem设置为0，但是上一个FB完成：*run_next = 1=》上一个FB完成的下一周期，初速度为0
            {
                if(*inter_flag == 1)
                {
                    *inter_save = 0;
                    *inter_flag = 0;
                }
                FB->buffer = false;
                FB->buffer_run = false;//和后面功能块运动的过渡曲线计算
                FB->TM_run_flag = false;

                *axesgroup_buffer_busy = 0;

                FB->run = true;//可以开始计算
            }

        }
            ///以给定的恒定速度过渡，即末速度不为0，末速度TP_V = TP* FB1->V（和标准不一样，以前一个功能块的速度的百分比为过渡速度）
            //不可以使用buffered，可以blending和aborting，初速度不为0，也可能为0
        else if(FB->TransitionMode == TMConstantVelocity)
        {
            if(mcAborting == FB->BufferMode)
            {
                if(*inter_flag != 1 ||(*inter_flag == 1 && fb_addr == *motionFB_addr))
                {
                    if(*inter_flag == 1)
                    {
                        *inter_save = 0;
                        *inter_flag = 0;
                    }
                    FB->run = true;
                }

            }
            else
            {
                /*进入缓冲区*/
                if(*axesgroup_buffer_busy == 0)
                {
                    FB->buffer = true;//FB处于buffer中，在缓冲区内
                    *axesgroup_buffer_busy = 1;//轴的buffer里存有FB

                    //缓冲区里的FB的混承模式和过渡模式信息
                    *axesgroup_transitionmode = TMConstantVelocity;
                    *axesgroup_buffermode = FB->BufferMode ;
                    *axesgroup_transitionparameter = FB->TransitionParameter ;
                    *axesgroup_buffer_motion_type = PTP;

                    //根据前一个运动的目标位置和目标方向 和 该FB运动的目标位置判断该轴是否可以进行混承!!!!

                    //每个轴当前的运动方向以及目标位置
                    for(int i = 0; i< *axis_sum_ingroup; i++)
                    {
                        axis_last_target_position[i] = axesgroup_axis_aimpulse[i];
                        now_axis_direction_p[i] =(int32_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * (axesgroup->i16_Axis_Num_In_Group[i]) + NOW_MOTION_DIRECTION]) ;
                    }
                    ACS_MCS_KinTrans_error = false;
                    //计算在ACS中每个轴 的目标脉冲值
                    if(FB->CoordSystem == ACS)
                    {
                        for(int i = 0; i< *axis_sum_ingroup; i++)
                        {
                            ACS_pos[i] = FB->Position[i] + axesgroup_ACS_relative_pos[i];//（旧原点）实际的ACS位置 = 新原点的ACS位置+新原点-旧原点的偏差值
                        }

                        for(int i = 0; i< *axis_sum_ingroup; i++)
                        {
                            /* 1、每个轴的目标角度 =》计算出目标的脉冲值；*/
                            mid_arr->aim_pulse[i] = ACS_pos[i]* (axesgroup_joint_directions[i]) * (axesgroup_joint_ratios[i]) + axesgroup_joint_offsets[i];
                        }
                    }
                    else //计算在MCS中每个轴 目标的脉冲值(PCS已经被换算到了MCS中）
                    {
                        //求逆解需要：当前每个轴的角度值
                        for(int i = 0; i< *axis_sum_ingroup; i++)
                        {
                            axis_last_target_angle[i] = (axis_last_target_position[i] -  axesgroup_joint_offsets[i]) * (axesgroup_joint_directions[i]) / (axesgroup_joint_ratios[i]);
                            //ARM987_actualJointAngles[1] := ARM987_jointDirections[1] * (ARM987_axis_array[1] - ARM987_jointOffsets[1]) / ARM987_gearRatios[1];
                        }
                        //根据目标位置，使用IK =》计算出每个轴的目标角度 =》计算出每个轴的目标脉冲值；
                        ACS_MCS_KinTransform(Task, FBIndex,axesgroup->ui8_Kin_Transform, 0, ACS_aimpos, &mid_arr->MCS_aimpos[0], &mid_arr->MCS_aimpos[1], &mid_arr->MCS_aimpos[2],&mid_arr->MCS_aimpos[3],&mid_arr->MCS_aimpos[4],
                                             &mid_arr->MCS_aimpos[5], axesgroup->f32_JointLimits, axis_last_target_angle, &ACS_MCS_KinTrans_error, &ACS_MCS_KinTrans_errorID, axesgroup->f32_DenHartA, axesgroup->f32_DenHartD);

                        for(int i = 0; i< *axis_sum_ingroup; i++)
                        {
                            /* 每个轴的目标角度 =》计算出目标的脉冲值；//pulsepos[timeFlag[index] ,index] * directions[index] * gearRatios[index] + offsets[index];*/
                            mid_arr->aim_pulse[i] = ACS_aimpos[i] * (axesgroup_joint_directions[i]) * (axesgroup_joint_ratios[i]) + axesgroup_joint_offsets[i];
                        }
                    }

                    ///##############z注意这里计算的 mid_arr->aim_pulse[i]和axis_last_target_position[i]都是基于上个运动到达目标位置的，
                    /// #############上方代码如需使用需要重新计算#################

                    if(ACS_MCS_KinTrans_error == true)
                    {
                        FB->Error = true;
                        FB->ErrorID = ParameterError;
                        FB->Busy = false;
                        FB->CommandAborted = false;
                        FB->exe = false;
                        FB->run = false;
                        FB->run_flag = false;
                        FB->buffer = false;
                        FB->buffer_run = false;
                        FB->TM_run_flag = false;
                        FB->run_numberF = 0;
                    }
                    else
                    {
                       // console_printf("\n ------ *axesgroup_buffer_busy == 0 TMConstantVelocity blending5------------///////////////-------\n");
                        for(int id = 0; id< *axis_sum_ingroup; id++)
                        {
                            axesgroup_axis_able_blending[id] = 1;
                            console_printf("#0 id = %d: mid_arr->aim_pulse[id] = %lf, axis_last_target_position[id]=%lf, *now_axis_direction_p[id] = %d\n",id,mid_arr->aim_pulse[id],axis_last_target_position[id],*now_axis_direction_p[id]);
                            //单轴前后运动方向相反，不混承
                            if((mid_arr->aim_pulse[id] >= axesgroup_axis_aimpulse[id] && (*now_axis_direction_p[id] < 0)) || (mid_arr->aim_pulse[id] <= axis_last_target_position[id] && (*now_axis_direction_p[id] > 0)))
                            {
                                axesgroup_axis_able_blending[id] = 0;
                                console_printf("#1 id = %d: mid_arr->aim_pulse[id] = %lf, axis_last_target_position[id]=%lf, *now_axis_direction_p[id] = %d\n",id,mid_arr->aim_pulse[id],axis_last_target_position[id],*now_axis_direction_p[id]);
                            }
                            //前后目标点距离过近也不混承  前后运动距离小于0.5度
                            if(fabs(mid_arr->aim_pulse[id] - axesgroup_axis_aimpulse[id])< axesgroup_joint_ratios[id]*0.5)
                            {
                                axesgroup_axis_able_blending[id] = 0;
                                console_printf("#2 id = %d: mid_arr->aim_pulse[id] = %lf, axis_last_target_position[id]=%lf, *now_axis_direction_p[id] = %d\n",id,mid_arr->aim_pulse[id],axis_last_target_position[id],*now_axis_direction_p[id]);

                            }
                            else
                            {
                                //轴正在进行的运动的最大速度 脉冲/毫秒
                                axis_n = axis_num_ingroup[id];
                                float *axis_now_motion_vel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + NOW_MOTION_VEL]);
                                //该功能块目标运动距离能允许的最大速度 v平方 = 2ds
                                float axis_velocity1 = sqrt(2 * mid_arr->every_axis_maxdec[id]*fabs(mid_arr->aim_pulse[id]-axesgroup_axis_aimpulse[id]));

                                //如果后一段距离太短，前一段的过渡速度太大，也不进行混成
                                if(axis_velocity1 < *axis_now_motion_vel)
                                {
                                    axesgroup_axis_able_blending[id] = 0;
                                    console_printf("#3 id = %d: axis_velocity1[id] = %lf, *axis_now_motion_vel[id]=%lf, \n",id,axis_velocity1,*axis_now_motion_vel);

                                }
                            }

                        }
                    }
                }

                /*等前一个任务执行完成，前一个FB运动末速度不为0,不需要等到 *run_next = 0*/
                if( *axesgroup_busy == 0 && ((FB->buffer &&*inter_flag != 1) ||(*inter_flag == 1 && fb_addr == *motionFB_addr)))//&& *run_next == 0)//每个周期开始都会被smallsystem设置为0，但是上一个FB完成：*run_next = 1=》上一个FB完成的下一周期，初速度为0
                {
                    if(*inter_flag == 1)
                    {
                        *inter_save = 0;
                        *inter_flag = 0;
                    }
                    *axesgroup_buffer_motion_type = NO_TYPE;
                    FB->buffer = false;
                    *axesgroup_buffer_busy = 0;
                    FB->run = true;//可以开始计算
                }
            }

        }

        else{}


    }

//这里计算的轨迹是在buffuer区没有下一个模块需要混承的情况，如果有的话，需要重新计算轨迹
    if(FB->run)
    {
        //console_printf("-------MoveDirectAbsolute: FB->Run -------\n");
        mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;
        if(*axesgroup_run_number==255)
        {
            *axesgroup_run_number = 1;//当前轴的运动编号，每个轴组只能被一个FB控制运动
        }
        else
        {
            *axesgroup_run_number = *axesgroup_run_number + 1;
        }
        FB->run_numberF = *axesgroup_run_number;//该FB的运动编号，如果运动编号与轴上运动编号不符，说明该运动被打断
        //*axesgroup_busy = 1;
        FB->exe = false;
        FB->buffer = false;
        FB->run = false;
        FB->max_finish_time = 0;


        *axesgroup_is_transition_motion = 0;
        //*axesgroup_blending_with_transition = 1; //初始化，正常blending都是有过渡曲线，如果后面有功能块混承会修改这个值(比如反向运动，应该为0

        //默认轴组使用位置模式
        for(int i = 0; i< POSITION_SIZE ; i++)
        {
            mid_arr->now_position[i] = axesgroup->f32_TCP_Target_Position[i];
            //计算目标位置相对于当前位置的方向，三维空间使用向量记录目标运动方向
            ///该向量不但记录方向，而且还记录距离
            mid_arr->aim_direction_distance[i] = mid_arr->MCS_aimpos[i] - mid_arr->now_position[i];
        }

        //计算FB指定的运动距离  只有数值，没有方向
        //x轴
        if(mid_arr->aim_direction_distance[0] < minp && mid_arr->aim_direction_distance[0] > ((-1)*minp))
        {
            FB->s_x = 0.0;
        }
        else if(mid_arr->aim_direction_distance[0] >= minp)
        {
            FB->s_x = mid_arr->aim_direction_distance[0];
        }
        else if( mid_arr->aim_direction_distance[0] <= ((-1)*minp))
        {
            FB->s_x = (-1)*mid_arr->aim_direction_distance[0];
        }else{}
        //y轴
        if(mid_arr->aim_direction_distance[1] < minp && mid_arr->aim_direction_distance[1] > ((-1)*minp))
        {
            FB->s_y = 0.0;
        }
        else if(mid_arr->aim_direction_distance[1] >= minp)
        {
            FB->s_y = mid_arr->aim_direction_distance[1];
        }
        else if( mid_arr->aim_direction_distance[1] <= ((-1)*minp))
        {
            FB->s_y = (-1)*mid_arr->aim_direction_distance[1];
        }else{}
        //z轴
        if(mid_arr->aim_direction_distance[2] < minp && mid_arr->aim_direction_distance[2] > ((-1)*minp))
        {
            FB->s_z = 0.0;
        }
        else if(mid_arr->aim_direction_distance[2] >= minp)
        {
            FB->s_z = mid_arr->aim_direction_distance[2];
        }
        else if( mid_arr->aim_direction_distance[2] <= ((-1)*minp))
        {
            FB->s_z = (-1)*mid_arr->aim_direction_distance[2];
        }else{}
        ///总距离
        FB->s = sqrt((FB->s_z*FB->s_z + FB->s_x*FB->s_x + FB->s_y*FB->s_y));


        /*计算初速度方向*/
        FB->tcp_vs =*axesgroup_now_tcp_vel;
        if(FB->tcp_vs >= minv)
        {
            for(int i = 0; i< DIRECTION_SIZE; i++)
            {
                //速度vs只有数值，没有方向；三维空间使用向量记录当前的运动方向*/
                mid_arr->now_direction_distance[i] = axesgroup_last_target_position[i] - axesgroup_last_last_target_position[i];
            }
        }
        else//速度为0，初速度方向与目标方向相同
        {
            for(int i = 0; i< DIRECTION_SIZE; i++)
            {
                mid_arr->now_direction_distance[i] = mid_arr->aim_direction_distance[i];
            }
        }

        /*运动轨迹类型*/
        if(FB->JerkFactor > 0)
        {
            FB->axis_run_mode = true;//S
        }
        else
        {
            FB->axis_run_mode = false;//T
        }
/*
        console_printf("\n FB->s= %lf,FB->s_x=%lf,FB->s_y=%lf,FB->s_z=%lf\n",FB->s,FB->s_x,FB->s_y,FB->s_z);
        for (int i = 0 ; i < 6; i ++)
        {
            console_printf(" mid_arr->aim_direction_distance[%d] = %lf \n  ",i,mid_arr->aim_direction_distance[i]);
        }
*/
        /**一开始就在目标位置*/
        if(FB->s < MIN_S_MM && fabs(mid_arr->aim_direction_distance[3]) < MIN_S_ANGLE && fabs(mid_arr->aim_direction_distance[4]) < MIN_S_ANGLE && fabs(mid_arr->aim_direction_distance[5]) < MIN_S_ANGLE)
        {
            FB->run_flag = false;
            FB->TM_run_flag = false;
            FB->Done = true;
            FB->CommandAborted = false;
            FB->Active = false;
            *axesgroup_busy = 0;

        }
        else
        {
            *axesgroup_state = MC_GroupMoving;

            //每个轴当前脉冲值
            for(int i = 0; i< *axis_sum_ingroup; i++)
            {

                axis_last_target_position_p = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * (axesgroup->i16_Axis_Num_In_Group[i]) + LAST_TARGET_POSITION]) ;
                axis_relative_position_p =  (double *) (&CassMem[AXIS_BASE + AXIS_SIZE *(axesgroup->i16_Axis_Num_In_Group[i]) + RELATIVE_POSITION]);
                axis_last_target_position[i] = *axis_last_target_position_p + *axis_relative_position_p;
            }

            ///计算每个轴的目标位置的脉冲值
            ACS_MCS_KinTrans_error = false;
            //计算在ACS中每个轴 moveabs的脉冲值
            if(FB->CoordSystem == ACS)
            {
                for(int i = 0; i< *axis_sum_ingroup; i++)
                {
                    ACS_pos[i] = FB->Position[i]*1.0 + axesgroup_ACS_relative_pos[i];//（旧原点）实际的ACS位置 = 新原点的ACS位置+新原点-旧原点的偏差值
                }

                for(int i = 0; i< *axis_sum_ingroup; i++)
                {
                    /* 1、每个轴的目标角度 =》计算出目标的脉冲值；*/
                    mid_arr->aim_pulse[i] = ACS_pos[i]* (axesgroup_joint_directions[i]) * (axesgroup_joint_ratios[i]) + axesgroup_joint_offsets[i];
                    //pulsepos[timeFlag[index] ,index] * directions[index] * gearRatios[index] + offsets[index];

                    aim_pulse_distance[i] = fabs(mid_arr->aim_pulse[i] - axis_last_target_position[i]);
                }
            }
                //计算在MCS中每个轴 moveabs需要的脉冲值(PCS已经被换算到了MCS中）
            else
            {

                //求逆解需要：当前每个轴的角度值
                for(int i = 0; i< *axis_sum_ingroup; i++)
                {

					axis_last_target_angle[i] = (axis_last_target_position[i] -  axesgroup_joint_offsets[i]) * (axesgroup_joint_directions[i]) / (axesgroup_joint_ratios[i]);
                    //ARM987_actualJointAngles[1] := ARM987_jointDirections[1] * (ARM987_axis_array[1] - ARM987_jointOffsets[1]) / ARM987_gearRatios[1];
                }

                //根据目标位置，使用IK =》计算出每个轴的目标角度 =》计算出每个轴的目标脉冲值；
                ACS_MCS_KinTransform(Task, FBIndex,axesgroup->ui8_Kin_Transform, 0, ACS_aimpos, &mid_arr->MCS_aimpos[0], &mid_arr->MCS_aimpos[1], &mid_arr->MCS_aimpos[2],&mid_arr->MCS_aimpos[3],&mid_arr->MCS_aimpos[4],
                                     &mid_arr->MCS_aimpos[5], axesgroup->f32_JointLimits, axis_last_target_angle, &ACS_MCS_KinTrans_error, &ACS_MCS_KinTrans_errorID, axesgroup->f32_DenHartA, axesgroup->f32_DenHartD);

                console_printf("FBDMC_MoveDirectAbsolute: acs_mcs_kinTransform error_id= %d :\n",ACS_MCS_KinTrans_errorID);
                for(int i = 0; i< *axis_sum_ingroup; i++)
                {
                    /* 每个轴的目标角度 =》计算出目标的脉冲值；//pulsepos[timeFlag[index] ,index] * directions[index] * gearRatios[index] + offsets[index];*/
                    axis_relative_position_p =  (double *) (&CassMem[AXIS_BASE + AXIS_SIZE *(axesgroup->i16_Axis_Num_In_Group[i]) + RELATIVE_POSITION]);
                    mid_arr->aim_pulse[i] = ACS_aimpos[i] * (axesgroup_joint_directions[i]) * (axesgroup_joint_ratios[i]) + axesgroup_joint_offsets[i] ;
                    aim_pulse_distance[i] = fabs(mid_arr->aim_pulse[i] - (axis_last_target_position[i]));
                    console_printf("FBDMC_MoveDirectAbsolute: aim_pulse[%d] = %lf,aim_pulse_distance[%d]=%lf;axis_last_target_position[i]=%lf\n"
																,i,mid_arr->aim_pulse[i],i,aim_pulse_distance[i],axis_last_target_position[i]);

                    //axesgroup_axis_aimpulse[i] = mid_arr->aim_pulse[i];//记录当前运动目标脉冲值
                }
            }
            ///求逆解不出错，则计算每个轴到目标位置的可以达到的最大速度和完成时间，保证有一个轴是最大速度，并且所有轴在 最长的完成时间 同时完成运动
            //运动时间最长的轴为完成时间；其他轴需要降低可以达到的最大速度，增大完成时间
            if(ACS_MCS_KinTrans_error == true)
            {
                //求逆解出错
                FB->Error = true;
                FB->ErrorID =  ACS_MCS_KinTransform_Error;
                FB->run_flag = false;
            }
            else
            {
                /**记录下当前运动的信息*/
                *axesgroup_now_motion_type = PTP;//运动类型
                axesgroup->f32_PTP_AccFactor = FB->AccFactor;
                axesgroup->f32_PTP_VelFactor = FB->VelFactor;
                axesgroup->f32_PTP_JerkFactor = FB->JerkFactor;
                for(int i = 0; i< POSITION_SIZE; i++)
                {
                    axesgroup_now_tcp_motion_aimpos[i] = mid_arr->MCS_aimpos[i];//运动目标位置
                }
                *axesgroup_now_tcp_motion_vel = 0;    /*PTP运动没有指定TCP的速度  */
                for(int i = 0; i< DIRECTION_SIZE; i++)
                {
                    axesgroup_now_tcp_motion_direction[i] = mid_arr->aim_direction_distance[i];//运动目标方向
                }
                for(int i = 0; i< *axis_sum_ingroup; i++)
                {
                    axesgroup_axis_aimpulse[i] = mid_arr->aim_pulse[i];//记录当前运动目标脉冲值
                }

                //判断哪些轴不需要运动
                for(int i = 0; i< *axis_sum_ingroup; i++)
                {
                    if(aim_pulse_distance[i] < MIN_S_PULSE)
                    {
                        mid_arr->axis_should_motion[i] = 0;
                    }
                }

                ///求最大完成时间；并且，根据最大完成时间分配速度
                if(false == FB->axis_run_mode)               /*梯形运动 三段：t1 t2 t3 加速度不变化*/
                {
                    ///如果该FB不是TMNone(有过渡曲线），初速度基本不为0
                    if (TMConstantVelocity == FB->TransitionMode) {
                        double t1, t2, t3, s1, s2, vs[AXIS_SUM_INGROUP_MAX], vm, s,  s_all, t_all, v1, state1_s, state2_s, rt1;
                        double acc[AXIS_SUM_INGROUP_MAX], dec[AXIS_SUM_INGROUP_MAX];
                        double t_1[AXIS_SUM_INGROUP_MAX], t_2[AXIS_SUM_INGROUP_MAX], t_3[AXIS_SUM_INGROUP_MAX], rt_1[AXIS_SUM_INGROUP_MAX];
                        int reverse[AXIS_SUM_INGROUP_MAX], mode[AXIS_SUM_INGROUP_MAX];
                        ///计算每个轴的完成时间，记录最大完成时间；并且，记录每个轴可以达到的最大速度及相应的完成时间
                        FB->max_finish_time = 0;
                        for (int i = 0; i < *axis_sum_ingroup; i++) {
                            if(0 == mid_arr->axis_should_motion[i])
                            {
                                continue;
                            }
                            //不使用moveVelocity，时间为0
                            mid_arr->MoveVel_time[i] = 0;

                            axis_n = axis_num_ingroup[i];
                            axis_now_velocity_p = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + NOW_VELOCITY]);
                            axis_now_velocity = *axis_now_velocity_p;

                            axis_relative_position_p =  (double *) (&CassMem[AXIS_BASE + AXIS_SIZE *(axesgroup->i16_Axis_Num_In_Group[i]) + RELATIVE_POSITION]);
                            axis_last_target_position_p = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * (axesgroup->i16_Axis_Num_In_Group[i]) + LAST_TARGET_POSITION]) ;
                            axis_last_target_position[i] =*axis_last_target_position_p + *axis_relative_position_p ;

                            if (mid_arr->aim_pulse[i] - axis_last_target_position[i] >= 0) {
                                mid_arr->axis_aim_direction[i] = 1;
                            } else {
                                mid_arr->axis_aim_direction[i] = -1;
                            }
                            /**计算初速度方向*/
                            if (axis_now_velocity >= min_vel_pulse) {
                                vs[i] = axis_now_velocity;
                                axis_now_direction[i] = 1;
                            } else if (axis_now_velocity <= (-1) * min_vel_pulse) {
                                vs[i] = (-1) * axis_now_velocity;
                                axis_now_direction[i] = -1;
                            } else {
                                vs[i] = 0;
                                axis_now_direction[i] = mid_arr->axis_aim_direction[i];
                            }
                            if (axis_now_direction[i] == mid_arr->axis_aim_direction[i]) {
                                reverse[i] = 0;
                            } else {
                                reverse[i] = 1;
                            }

                            s = fabs(aim_pulse_distance[i]);//运动总距离
                            acc[i] = mid_arr->every_axis_maxacc[i];
                            dec[i] = mid_arr->every_axis_maxdec[i];
                            axis_max_v1[i] = mid_arr->every_axis_maxvel[i];//不规定时间，完成运动 实际 可以达到的最大速度

                            vm = 0.0;
                            T_Motion(axis_max_v1[i], vs[i], vm, s, acc[i], dec[i], reverse[i],//输入量
                                     &mode[i], &t1, &t2, &t3, &s1, &s2, &s_all, &t_all, //输出量
                                     &state1_s, &state2_s,   //输出量
                                     &v1, &rt1);
                            axis_max_v1[i] = v1;//实际可以达到的最大速度



                            //最大完成时间及对应单轴组内id
                            axis_finish_time[i] = t1 + t2 + t3 + rt1;
                            if (FB->max_finish_time < axis_finish_time[i] + 1) {
                                FB->max_finish_time = axis_finish_time[i] + 1;
                                FB->max_finish_time_id = i;
                            }

                            //记录数据
                            t_1[i] = t1;
                            t_2[i] = t2;
                            t_3[i] = t3;
                            rt_1[i] = rt1;

                           // console_printf("\naxisid == 0: axis_max_v1[i]= %lf,s1=%lf,s-s1 =%lf ,t1=%lf\n", axis_max_v1[i], s1,(s - s1), t1);

                        }
                        ///根据最大完成时间分配速度
                       // console_printf("\n---------T: solve axis_max_v2:---------\n");
                        for (int i = 0; i < *axis_sum_ingroup; i++) {
                            if(0 == mid_arr->axis_should_motion[i])
                            {
                                continue;
                            }

                            axis_max_v2[i] = axis_max_v1[i];
                            if (i != FB->max_finish_time_id) {
                                //如果axis_finish_time[i]和FB->max_finish_time相差不超过一个周期，则不进行调整
                                //deviation_t 偏差的最小可接受周期数
                                //#define CLK_PERIOD   1  一个周期的时间 1ms
                                if (axis_finish_time[i] > FB->max_finish_time - deviation_t * CLK_PERIOD) {
                                    //相差不超过一个周期，则不进行调整
                                }
                                    //相差超过一个周期，减小可以达到的最大速度
                                else {
                                    //DEC_ALL || DEC_EQU_DEC 初速度和实际能达到的最大速度  因为在正常ACC_EQU_DEC时，也可能最大速度只能达到vs，运动整个都为减速
                                    if (reverse[i] == 0 && vs[i] >= axis_max_v1[i]) {

                                        //初速度太大的，无法调整时间，因为在初速度下降为最大速度之前就已经走完了所有路程 即t_2[i]=0, vs[i] / acc > FB->max_finish_time
                                        if (t_2[i] <= 1) //匀速时间少于1个周期 说明该运动剩余距离仅用于减速可能还不够降速为0，无法延长时间
                                        {
                                            axis_max_v2[i] = axis_max_v1[i];//不调整时间，该轴会最先完成
                                        } else {
                                            axis_max_v2[i] = axis_max_v1[i] * t_2[i] /
                                                             (FB->max_finish_time - axis_finish_time[i] + t_2[i]);
                                        }
                                    }
                                        //ACC_EQU_DEC 初速度和实际能达到的最大速度
                                    else if (reverse[i] == 0 && vs[i] < axis_max_v1[i]) {
                                        //梯形完整
                                        if (vs[i] < min_vel_pulse) {
                                            axis_max_v2[i] = axis_max_v1[i] * (FB->max_finish_time -
                                                                               sqrt(FB->max_finish_time *
                                                                                    FB->max_finish_time -
                                                                                    axis_finish_time[i] *
                                                                                    axis_finish_time[i] +
                                                                                    t_2[i] * t_2[i])) /
                                                             (axis_finish_time[i] - t_2[i]);
                                        } else//补全梯形
                                        {

                                            double max_finish_time1 = FB->max_finish_time + vs[i] / acc[i];
                                            double axis_finish_time1 = axis_finish_time[i] + vs[i] / acc[i];
                                            axis_max_v2[i] = axis_max_v1[i] * (max_finish_time1 -
                                                                               sqrt(max_finish_time1 *
                                                                                    max_finish_time1 -
                                                                                    axis_finish_time1 *
                                                                                    axis_finish_time1 +
                                                                                    t_2[i] * t_2[i])) /
                                                             (axis_finish_time1 - t_2[i]);
                                            //不适合补全梯形
                                            if(vs[i] > axis_max_v2[i]+1)
                                            {
                                                if(t_2[i] < 0.000001)//匀速周期小于0.000001忽略不计
                                                {
                                                    axis_max_v2[i] = ( axis_max_v1[i]+vs[i])*(axis_finish_time[i]-vs[i]/dec[i])/(2*(FB->max_finish_time - vs[i]/dec[i]));

                                                   //console_printf ("\n---i= %d  --- axis_max_v2[i] = %lf axis_max_v1[i]=%lf vs[i]=%lf axis_finish_time[i]=%lf dec[i] = %lf\n FB->max_finish_time=%lf\n", i,axis_max_v2[i],axis_max_v1[i],vs[i],axis_finish_time[i],dec[i],FB->max_finish_time);
                                                }
                                                else
                                                {
                                                    //axis_max_v2[i] = ((axis_max_v1[i]-vs[i])*(axis_finish_time[i]-vs[i]/dec[i]+t_2[i])+2*(axis_finish_time[i]-vs[i]/dec[i])*vs[i])/(2*(FB->max_finish_time - vs[i]/dec[i]));
                                                    double xx = 2*(dec[i]*FB->max_finish_time - vs[i]);
                                                    axis_max_v2[i] = ((axis_finish_time[i]*dec[i]-vs[i])*(vs[i]+axis_max_v1[i])+dec[i]*t_2[i]*(axis_max_v1[i]-vs[i]))/xx;

                                                    //console_printf ("\n#2#i= %d --- axis_max_v2[i] = %lf axis_max_v1[i]=%lf vs[i]=%lf axis_finish_time[i]=%lf dec[i] = %lf\n FB->max_finish_time=%lf t_2[i]=%lf\n", i,axis_max_v2[i],axis_max_v1[i],vs[i],axis_finish_time[i],dec[i],FB->max_finish_time,t_2[i]);

                                                }

                                            }


                                        }
                                    } else {
                                        double max_finish_time1 = FB->max_finish_time - rt_1[i];
                                        double axis_finish_time1 = axis_finish_time[i] - rt_1[i];
                                        axis_max_v2[i] = axis_max_v1[i] * (max_finish_time1 -
                                                                           sqrt(max_finish_time1 * max_finish_time1 -
                                                                                axis_finish_time1 * axis_finish_time1 +
                                                                                t_2[i] * t_2[i])) /
                                                         (axis_finish_time1 - t_2[i]);

                                    }
                                }
                            }
                            if (axis_max_v2[i] != axis_max_v2[i]) {
                                console_printf("\n\nerror!!!i = %d (FB->max_finish_time*FB->max_finish_time - axis_finish_time[i]*axis_finish_time[i] + t_2[i]*t_2[i]) = %lf\n(axis_finish_time[i](%lf) - t_2[i](%lf)= %lf\n",
                                       i,
                                       (FB->max_finish_time * FB->max_finish_time -
                                        axis_finish_time[i] * axis_finish_time[i] + t_2[i] * t_2[i]),
                                       axis_finish_time[i], t_2[i], (axis_finish_time[i] - t_2[i]));
                            }
                        }

                        //console_printf("FB->max_finish_time = %lf ms FB->max_finish_time_id = %d\n", FB->max_finish_time,FB->max_finish_time_id);
                        for (int i = 0; i < *axis_sum_ingroup; i++) {
                            if(0 == mid_arr->axis_should_motion[i])
                            {
                                continue;
                            }
                            mid_arr->axis_max_vel[i] = axis_max_v2[i];
                           // console_printf("mid_arr->axis_max_vel[%d]= %lf\n", i, mid_arr->axis_max_vel[i]);
                        }

                    }


                        ///如果该FB是TMNone-Abort||buffered（没有过渡曲线），初速度应该为0
                    else if (TMNone == FB->TransitionMode) {
                        //初速度值不为0，说明上一个模块过渡计算错误
                        if (FB->tcp_vs >= 1) {
                            FB->run_flag = false;
                            FB->Error = true;
                            FB->ErrorID = Transition_Compute_Error;
                            console_printf("\n------------T梯形---Transition_Compute_Error------FB->tcp_vs = %lf-------\n",FB->tcp_vs);
                        }
                        else {
                            double t1, t2, t3, s1, vs, s, acc, dec;
                            double t_1[AXIS_SUM_INGROUP_MAX], t_2[AXIS_SUM_INGROUP_MAX], t_3[AXIS_SUM_INGROUP_MAX];
                            //初速度必然小于最大速度
                            ///计算每个轴的完成时间，记录最大完成时间；并且，记录每个轴可以达到的最大速度及相应的完成时间
                            FB->max_finish_time = 0;
                            for (int i = 0; i < *axis_sum_ingroup; i++) {
                                if(0 == mid_arr->axis_should_motion[i])
                                {
                                    continue;
                                }

                                //不使用moveVelocity，时间为0
                                mid_arr->MoveVel_time[i] = 0;

                                vs = 0.0;//初速度为0
                                s = fabs(aim_pulse_distance[i]);//运动总距离
                                acc = mid_arr->every_axis_maxacc[i];
                                dec = mid_arr->every_axis_maxdec[i];
                                axis_max_v1[i] = mid_arr->every_axis_maxvel[i];//不规定时间，完成运动 实际 可以达到的最大速度
                                t1 = (axis_max_v1[i]) / mid_arr->every_axis_maxacc[i];
                                t3 = (axis_max_v1[i]) / mid_arr->every_axis_maxdec[i];
                                s1 = mid_arr->every_axis_maxacc[i] * t1 * t1 / 2.0 + axis_max_v1[i] * t3 -
                                     mid_arr->every_axis_maxdec[i] * t3 * t3 / 2.0;//加速度+减速段路程

                                t2 = (s - s1) / axis_max_v1[i];
                                //t2 < 0，即达不到最大速度
                                if (t2 < 0) {
                                    t2 = 0;
                                    t1 = (sqrt(vs * vs - acc * (vs * vs - 2.0 * dec * s) / (acc + dec)) - vs) /
                                         acc;//由：末速度平方 - 初速度平方 = 2*a*s公式推导
                                    t3 = (vs + acc * t1) / dec;
                                    axis_max_v1[i] = vs + acc * t1;//实际可以达到的最大速度
                                }

                                //最大完成时间及对应单轴组内id
                                axis_finish_time[i] = t1 + t2 + t3;
                                if (FB->max_finish_time < axis_finish_time[i] + 1) {
                                    FB->max_finish_time = axis_finish_time[i] + 1;
                                    FB->max_finish_time_id = i;
                                }

                                //记录数据
                                t_1[i] = t1;
                                t_2[i] = t2;
                                t_3[i] = t3;

                            }

                            ///根据最大完成时间分配速度
                            //console_printf("\n---------T: solve axis_max_v2:---------\n");
                            for (int i = 0; i < *axis_sum_ingroup; i++) {
                                if(0 == mid_arr->axis_should_motion[i])
                                {
                                    continue;
                                }

                                axis_max_v2[i] = axis_max_v1[i];
                                if (i != FB->max_finish_time_id) {
                                    //如果axis_finish_time[i]和FB->max_finish_time相差不超过一个周期，则不进行调整
                                    //deviation_t 偏差的最小可接受周期数
                                    //#define CLK_PERIOD   1  一个周期的时间 1ms
                                    if (axis_finish_time[i] > FB->max_finish_time - deviation_t * CLK_PERIOD) {
                                        //相差不超过一个周期，则不进行调整
                                    }
                                        //相差超过一个周期，减小可以达到的最大速度
                                    else {
                                        //由梯形面积公式推导而来，一元二次方程的两个解中取较小的解（v2 < v1）

                                        axis_max_v2[i] = axis_max_v1[i] * (FB->max_finish_time -
                                                                           sqrt(FB->max_finish_time *
                                                                                FB->max_finish_time -
                                                                                axis_finish_time[i] *
                                                                                axis_finish_time[i] +
                                                                                t_2[i] * t_2[i])) /
                                                         (axis_finish_time[i] - t_2[i]);

                                    }
                                }
                                /*
                                if (axis_max_v2[i] != axis_max_v2[i]) {
                                    console_printf("i = %d (FB->max_finish_time*FB->max_finish_time - axis_finish_time[i]*axis_finish_time[i] + t_2[i]*t_2[i]) = %lf\n(axis_finish_time[i](%lf) - t_2[i](%lf)= %lf\n",
                                           i,
                                           (FB->max_finish_time * FB->max_finish_time -
                                            axis_finish_time[i] * axis_finish_time[i] + t_2[i] * t_2[i]),
                                           axis_finish_time[i], t_2[i], (axis_finish_time[i] - t_2[i]));
                                } */
                            }

                            console_printf("FB->max_finish_time = %lfms FB->max_finish_time_id = %d\n", FB->max_finish_time,FB->max_finish_time_id);
                            for (int i = 0; i < *axis_sum_ingroup; i++) {
                                if(0 == mid_arr->axis_should_motion[i])
                                {
                                    continue;
                                }
                                mid_arr->axis_max_vel[i] = axis_max_v2[i];
                                console_printf("mid_arr->axis_max_vel[%d]= %lf/ms\n", i, mid_arr->axis_max_vel[i]);
                            }

                        }
                    }
                }
                else /*S形运动 7段：t1 t2... t7 加速度变化*/
                {
                    //由梯形曲线转换到S形曲线
                    double t1, t2, t3, s1, s2, vs[AXIS_SUM_INGROUP_MAX], vm, s, s_all, t_all, v1, state1_s, state2_s, rt1;
                    double acc[AXIS_SUM_INGROUP_MAX], dec[AXIS_SUM_INGROUP_MAX];
                    double t_1[AXIS_SUM_INGROUP_MAX], t_2[AXIS_SUM_INGROUP_MAX], t_3[AXIS_SUM_INGROUP_MAX], rt_1[AXIS_SUM_INGROUP_MAX];
                    int reverse[AXIS_SUM_INGROUP_MAX], mode[AXIS_SUM_INGROUP_MAX];
                    ///使用梯形运动 计算每个轴的完成时间，记录最大完成时间；并且，记录每个轴可以达到的最大速度及相应的完成时间
                    FB->max_finish_time = 0;
                    for (int i = 0; i < *axis_sum_ingroup; i++) {
                        if(0 == mid_arr->axis_should_motion[i])
                        {
                            continue;
                        }
                        axis_n = axis_num_ingroup[i];
                        axis_now_velocity_p = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + NOW_VELOCITY]);
                        axis_now_velocity = *axis_now_velocity_p;

						axis_relative_position_p =  (double *) (&CassMem[AXIS_BASE + AXIS_SIZE *(axesgroup->i16_Axis_Num_In_Group[i]) + RELATIVE_POSITION]);
                        axis_last_target_position_p = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * (axesgroup->i16_Axis_Num_In_Group[i]) + LAST_TARGET_POSITION]) ;
                        axis_last_target_position[i] =*axis_last_target_position_p  + *axis_relative_position_p;
                        if (mid_arr->aim_pulse[i] - axis_last_target_position[i] >= 0) {
                            mid_arr->axis_aim_direction[i] = 1;
                        } else {
                            mid_arr->axis_aim_direction[i] = -1;
                        }
                        /**计算初速度方向*/
                        if (axis_now_velocity >= min_vel_pulse) {
                            vs[i] = axis_now_velocity;
                            axis_now_direction[i] = 1;
                        } else if (axis_now_velocity <= (-1) * min_vel_pulse) {
                            vs[i] = fabs(axis_now_velocity);
                            axis_now_direction[i] = -1;
                        } else {
                            vs[i] = 0;
                            axis_now_direction[i] = mid_arr->axis_aim_direction[i];
                        }
                        if (axis_now_direction[i] == mid_arr->axis_aim_direction[i]) {
                            reverse[i] = 0;
                        } else {
                            reverse[i] = 1;
                        }

                        s = fabs(aim_pulse_distance[i]);//运动总距离
                        acc[i] = mid_arr->every_axis_maxacc[i]/2.0; //梯形加速度是S形最大加速度的一半
                        dec[i] = mid_arr->every_axis_maxdec[i]/2.0;//梯形减速度是S形最大减速度的一半
                        axis_max_v1[i] = mid_arr->every_axis_maxvel[i];//不规定时间，完成运动 实际 可以达到的最大速度

                        vm = 0.0;
                        // &mode[i]为无用赋值，后面会再次给mode赋值,此处只是需要一个输出量
                        T_Motion(axis_max_v1[i], vs[i], vm, s, acc[i], dec[i], reverse[i],//输入量
                                 &mode[i], &t1, &t2, &t3, &s1, &s2, &s_all, &t_all, //输出量
                                 &state1_s, &state2_s,   //输出量
                                 &v1, &rt1);
                        axis_max_v1[i] = v1;//实际可以达到的最大速度



                        //最大完成时间及对应单轴组内id
                        axis_finish_time[i] = t1 + t2 + t3 + rt1;
                        if (FB->max_finish_time < axis_finish_time[i] + 1) {
                            FB->max_finish_time = axis_finish_time[i] + 1;
                            FB->max_finish_time_id = i;
                        }

                        //记录数据
                        t_1[i] = t1;
                        t_2[i] = t2;
                        t_3[i] = t3;
                        rt_1[i] = rt1;
                        console_printf("\n  i = %d  axis_now_velocity = %lf  reverse[i]=%d  axis_last_target_position[i]=%lf\n",i,axis_now_velocity,reverse[i], axis_last_target_position[i]);
                        //if (i == 0) {console_printf("\naxisid == 0: axis_max_v1[i]= %lf,s1=%lf,s-s1 =%lf ,t1=%lf\n", axis_max_v1[i],s1,}
                    }
                    ///根据最大完成时间分配速度 以及求所有轴的mode FB->max_finish_time_id的v2=v1
                    console_printf("\n---------S: solve axis_max_v2:---------\n");
                    for (int i = 0; i < *axis_sum_ingroup; i++) {
                        if(0 == mid_arr->axis_should_motion[i])
                        {
                            continue;
                        }
                        axis_max_v2[i] = axis_max_v1[i];
                        //deviation_t 偏差的最小可接受周期数
                        //#define clk_period   1  一个周期的时间 1ms
                        //if (axis_finish_time[i] > FB->max_finish_time - deviation_t * CLK_PERIOD) {
                        //相差不超过一个周期，则不进行调整

                        //相差超过一个周期，减小可以达到的最大速度
                        //由梯形面积公式推导而来，一元二次方程的两个解中取较小的解（v2 < v1）
                        //DEC_ALL || DEC_EQU_DEC 初速度和实际能达到的最大速度  因为在正常ACC_EQU_DEC时，也可能最大速度只能达到vs，运动整个都为减速(DEC_ALL)
                        if (reverse[i] == 0 && vs[i] >= axis_max_v1[i]-0.0001) {

                            //DEC_ALL初速度太大的，无法调整时间，因为在初速度下降为最大速度之前就已经走完了所有路程 即t_2[i]=0, vs[i] / acc > FB->max_finish_time
                            if (t_2[i] <= 1) //匀速时间少于1个周期 说明该运动剩余距离仅用于减速可能还不够降速为0，无法延长时间
                            {
                                axis_max_v2[i] = axis_max_v1[i];//不调整时间，该轴会最先完成
                                mode[i] = 1;//调整时间之前的梯形运动轨迹DEC_ALL
                            } else {
                                axis_max_v2[i] = axis_max_v1[i] * t_2[i] /
                                                 (FB->max_finish_time - axis_finish_time[i] + t_2[i]);
                                mode[i] = 2;//调整时间之前的梯形运动轨迹DEC_EQU_DEC
                            }
                        }
                            //ACC_EQU_DEC 初速度和实际能达到的最大速度
                        else if (reverse[i] == 0 && vs[i] < axis_max_v1[i]) {
                            //梯形完整
                            if (vs[i] < min_vel_pulse) {
                                axis_max_v2[i] = axis_max_v1[i] * (FB->max_finish_time -
                                                                   sqrt(FB->max_finish_time *
                                                                        FB->max_finish_time -
                                                                        axis_finish_time[i] *
                                                                        axis_finish_time[i] +
                                                                        t_2[i] * t_2[i])) /
                                                 (axis_finish_time[i] - t_2[i]);
                                mode[i] = 3;//调整时间之前的梯形运动轨迹ACC_EQU_DEC ||ACC_DEC
                            }
                            else//补全梯形
                            {
                                double max_finish_time1 = FB->max_finish_time + vs[i] / acc[i];
                                double axis_finish_time1 = axis_finish_time[i] + vs[i] / acc[i];
                                axis_max_v2[i] = axis_max_v1[i] * (max_finish_time1 -
                                                                   sqrt(max_finish_time1 *
                                                                        max_finish_time1 -
                                                                        axis_finish_time1 *
                                                                        axis_finish_time1 +
                                                                        t_2[i] * t_2[i])) /
                                                 (axis_finish_time1 - t_2[i]);
                                mode[i] = 3;//调整时间之前的梯形运动轨迹ACC_EQU_DEC ||ACC_DEC

                                //不适合补全梯形
                                if(vs[i] > axis_max_v2[i])
                                {
                                    if(t_2[i] < 0.000001)//匀速周期小于0.000001忽略不计
                                    {
                                        axis_max_v2[i] = ( axis_max_v1[i]+vs[i])*(axis_finish_time[i]-vs[i]/dec[i])/(2*(FB->max_finish_time - vs[i]/dec[i]));

                                        mode[i] = 2;//调整时间之前的梯形运动轨迹DEC_EQU_DEC
                                        console_printf ("\n---i= %d  mode[i] = %d--- axis_max_v2[i] = %lf axis_max_v1[i]=%lf vs[i]=%lf axis_finish_time[i]=%lf dec[i] = %lf\n FB->max_finish_time=%lf\n", i,mode[i],axis_max_v2[i],axis_max_v1[i],vs[i],axis_finish_time[i],dec[i],FB->max_finish_time);
                                    }
                                    else
                                    {
                                        axis_max_v2[i] = ((axis_max_v1[i]-vs[i])*(axis_finish_time[i]-vs[i]/dec[i]+t_2[i])+2*(axis_finish_time[i]-vs[i]/dec[i])*vs[i])/(2*(FB->max_finish_time - vs[i]/dec[i]));

                                        mode[i] = 2;//调整时间之前的梯形运动轨迹DEC_EQU_DEC
                                        console_printf ("\n#2#i= %d  mode[i] = %d--- axis_max_v2[i] = %lf axis_max_v1[i]=%lf vs[i]=%lf axis_finish_time[i]=%lf dec[i] = %lf\n FB->max_finish_time=%lf\n", i,mode[i],axis_max_v2[i],axis_max_v1[i],vs[i],axis_finish_time[i],dec[i],FB->max_finish_time);

                                    }

                                }

                            }

                        } else {
                            double max_finish_time1 = FB->max_finish_time - rt_1[i];
                            double axis_finish_time1 = axis_finish_time[i] - rt_1[i];
                            axis_max_v2[i] = axis_max_v1[i] * (max_finish_time1 -
                                                               sqrt(max_finish_time1 * max_finish_time1 -
                                                                    axis_finish_time1 * axis_finish_time1 +
                                                                    t_2[i] * t_2[i])) /
                                             (axis_finish_time1 - t_2[i]);
                            mode[i] = 4;//调整时间之前的梯形运动轨迹reverse
                        }
                        if (i == FB->max_finish_time_id)
                        {
                            axis_max_v2[i] = axis_max_v1[i];
                        }
                        if (axis_max_v2[i] != axis_max_v2[i]) {
                            console_printf("\n\nerror!!!i = %d (FB->max_finish_time*FB->max_finish_time - axis_finish_time[i]*axis_finish_time[i] + t_2[i]*t_2[i]) = %lf\n(axis_finish_time[i](%lf) - t_2[i](%lf)= %lf\n",
                                   i,
                                   (FB->max_finish_time * FB->max_finish_time -
                                    axis_finish_time[i] * axis_finish_time[i] + t_2[i] * t_2[i]),
                                   axis_finish_time[i], t_2[i], (axis_finish_time[i] - t_2[i]));
                        }
                    }
                    console_printf("FB->max_finish_time = %lfs FB->max_finish_time_id = %d\n", FB->max_finish_time,
                           FB->max_finish_time_id);
                    for (int i = 0; i < *axis_sum_ingroup; i++) {
                        if(0 == mid_arr->axis_should_motion[i])
                        {
                            continue;
                        }
                        mid_arr->axis_max_vel[i] = axis_max_v2[i];
                        console_printf("mid_arr->axis_max_vel[%d]= %lf\n", i, mid_arr->axis_max_vel[i]);
                    }

                    //所有轴都只计算了梯形，所以都要转换
                    //把 每个轴 的梯形曲线转换成S形曲线（调整jerk） movevel（acc,dec,j1,time) moveabs（acc,dec,j2,aim_pulse) acc dec aim_pulse,axis_max_vel不变
                    for (int i = 0; i < *axis_sum_ingroup; i++)
                    {
                        if(0 == mid_arr->axis_should_motion[i])
                        {
                            continue;
                        }
                        double t22,t21,t23;
                        if(1 == mode[i])//调整时间之前的梯形运动轨迹DEC_ALL
                        {
                            mid_arr->MoveVel_time[i] = -1;//表示，不运行movevel，但是要调整moveabs的jerk
                            //t_dec = axis_max_v2[i]/FB->max_finish_time, jerk下降
                            mid_arr->MoveAbs_JERK2[i] = (4.0 * (axis_max_v2[i]/FB->max_finish_time))/FB->max_finish_time;//2*dec = mid_arr->every_axis_maxdec
                        }
                        else if(2 == mode[i])//调整时间之前的梯形运动轨迹DEC_EQU_DEC
                        {
                            t21 = (vs[i] - axis_max_v2[i]) / dec[i];
                            //防止t21过于小，导致jerk无限大
                            if(t21 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏小
                            {
                                mid_arr->MoveVel_JERK1[i] =mid_arr->every_axis_jerk[i];
                            }
                            else
                            {
                                mid_arr->MoveVel_JERK1[i] = (4.0 * dec[i])/t21;//最大为减速度（2dec）的4倍
                            }
                            t23 = axis_max_v2[i] / dec[i];
                            //防止t23过于小，导致jerk无限大
                            if(t23 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏大
                            {
                                mid_arr->MoveAbs_JERK2[i] =mid_arr->every_axis_jerk[i];
                            }
                            else
                            {
                                mid_arr->MoveAbs_JERK2[i] = (4.0 * dec[i])/t23;
                            }
                            mid_arr->MoveVel_time[i] = FB->max_finish_time - t23;
                        }
                        else if(3 == mode[i])//调整时间之前的梯形运动轨迹ACC_EQU_DEC ||ACC_DEC
                        {
                            t23 = axis_max_v2[i]/dec[i];
                            //防止t23过于小，导致jerk无限大
                            if(t23 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏大
                            {
                                mid_arr->MoveAbs_JERK2[i] =mid_arr->every_axis_jerk[i];
                            }
                            else
                            {
                                mid_arr->MoveAbs_JERK2[i] = (4.0 * dec[i])/t23;
                            }
                            mid_arr->MoveVel_time[i] = FB->max_finish_time - t23;

                            if(vs[i] < axis_max_v2[i])
                            {
                                t21 = (axis_max_v2[i] - vs[i])/acc[i];
                                //防止t21过于小，导致jerk无限大
                                if(t21 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏小
                                {
                                    mid_arr->MoveVel_JERK1[i] =mid_arr->every_axis_jerk[i];
                                }
                                else
                                {
                                    mid_arr->MoveVel_JERK1[i] = (4.0 * acc[i])/t21;
                                }
                            }
                            else
                            {
                                t21 = (vs[i] - axis_max_v2[i] )/acc[i];
                                //防止t21过于小，导致jerk无限大
                                if(t21 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏小
                                {
                                    mid_arr->MoveVel_JERK1[i] =mid_arr->every_axis_jerk[i];
                                }
                                else
                                {
                                    mid_arr->MoveVel_JERK1[i] = (4.0 * dec[i])/t21;
                                }
                            }
                        }
                        else if(4 == mode[i]) //reverse acc_equ_dec
                        {
                            t23 = axis_max_v2[i]/dec[i];
                            //防止t23过于小，导致jerk无限大
                            if(t23 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏大
                            {
                                mid_arr->MoveAbs_JERK2[i] =mid_arr->every_axis_jerk[i];
                            }
                            else
                            {
                                mid_arr->MoveAbs_JERK2[i] = (4.0 * dec[i])/t23;
                            }
                            mid_arr->MoveVel_time[i] = FB->max_finish_time - t23;

                            t21 = axis_max_v2[i]/acc[i] + rt_1[i];
                            //防止t21过于小，导致jerk无限大
                            if(t21 < 0.5)//四舍五入，当加速时间小于0.5周期时，不调整jerk；总路程偏小
                            {
                                mid_arr->MoveVel_JERK1[i] =mid_arr->every_axis_jerk[i];
                            }
                            else
                            {
                                mid_arr->MoveVel_JERK1[i] = (4.0 * acc[i])/t21;
                            }
                        }

                    }

                }///S形曲线

                FB->t_now = (float)Task->taskPeriod / 1000;
                if(FB->Error != true)
                {
                    FB->run_flag = true;
                }
                else{
                    FB->run_flag = false;
                }
            }///求逆解不出错，则计算每个轴到目标位置的可以达到的最大速度和完成时间
        }/**一开始就在目标位置*/
    }///if(fb->run)

    //被interrupt中断
    if((FB->run_flag == true  || FB->TM_run_flag == true) && *axesgroup_run_number != FB->run_numberF)
    {
        if(*inter_flag == 1)
        {   //在过渡期被中断和不运动时被中断一样
            if(FB->TM_run_flag == true)
            {
                *motionFB_num = 0;
                *motionFB_addr = 0;//保存当前功能块对象地址
                *inter_save = 0;
            }
            else{
                *motionFB_num = MC_MOVEDIRECTABSOLUTE;
                *motionFB_addr = (uint64_t)FB;//保存当前功能块对象地址
                *inter_save = 1;
            }

        }
    }


///TM_run_flag 负责过渡阶段每周期的运动  这里的代码只包括打断后速度降为0的运动
    if(FB->TM_run_flag == true)
    {
        *axesgroup_is_transition_motion = 1;
        //FB->run_flag =false; 前面一个功能块如果需要停止会被打断，不需要停止的继续运行
        mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;
        if(*axesgroup_run_number != FB->run_numberF)     /**运动被打断*/
        {
            FB->CommandAborted = true;
            FB->run_flag = false;
            FB->TM_run_flag = false;
            FB->run_numberF = 0;
            FB->Active = false;
            FB->Done = false;
            FB->Busy = false;
        }
        else
        {
            FB->Active = true;
            *axesgroup_busy = 1;
            if(1 == FB->tm_mode ) {//TMNone
                FB->all_axis_done = 1;
                //启动moveabs的代码
                for(int id = 0; id<*axis_sum_ingroup;id++)
                {
                    if(0 == mid_arr->axis_should_motion[id])
                    {
                        continue;
                    }
                    if(mid_arr->FB_TM_Halt[id].Execute != 1)// &&FB->Execute == 1)
                    {
                        console_printf("\n-------------PTP-TM_run_flag:-----------------\n");
                        console_printf("id = %d if(FB_TM_Halt[id].Execute =%d &&FB->Execute=%d)mid_arr->aim_pulse[id]=%lf \n",id,mid_arr->FB_TM_Halt[id].Execute,FB->Execute,mid_arr->aim_pulse[id]);

                        mid_arr->FB_TM_Halt[id].Execute = 1 ;
                        mid_arr->FB_TM_Halt[id].execute_before = 0 ;
                        mid_arr->FB_TM_Halt[id].Axis_num = axis_num_ingroup[id] ;
                        mid_arr->FB_TM_Halt[id].Deceleration = mid_arr->every_axis_maxdec[id]* 1000000.0 ;
                        mid_arr->FB_TM_Halt[id].Jerk = mid_arr->every_axis_jerk[id] * 1000000000.0 ;
                        console_printf("FB_Stop: id=%d DEC=%lf JERK=%lf\n",id,mid_arr->FB_TM_Halt[id].Deceleration,
                               mid_arr->FB_TM_Halt[id].Jerk);
                    }

                    axis_n = axis_num_ingroup[id];
                    axis_state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + STATE]);
                   // *axis_state = MC_Discrete_Motion;
                    FBDMC_Halt(Task, FBIndex, &mid_arr->FB_TM_Halt[id]);
                    //*axis_state = MC_Synchronized_Motion;

                    //输出量
                    if(mid_arr->FB_TM_Halt[id].Error == 1)
                    {
                        FB->run_flag = false;
                        FB->TM_run_flag = false;
                        FB->Error = true;

                        if(mid_arr->FB_TM_Halt[id].ErrorID == StateError)
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_StateError;
                        }
                        else if(mid_arr->FB_TM_Halt[id].ErrorID == ParameterError)
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_ParameterError;
                        }
                        else
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_OtherError;
                        }

                        FB->run_numberF = 0;
                        FB->Active = false;
                        FB->Done = false;
                        FB->Busy = false;
                        console_printf("\nmid_arr->FB_TM_Halt[%d].Error == 1:axis_error = %d\n",id,mid_arr->FB_TM_Halt[id].ErrorID);
                        break;
                    }
                    else  if(mid_arr->FB_TM_Halt[id].CommandAborted == 1)
                    {

                        FB->run_flag = false;
                        FB->TM_run_flag = false;
                        FB->Error = true;
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_CommandAborted_Error;
                        FB->run_numberF = 0;
                        FB->Active = false;
                        FB->Done = false;
                        FB->Busy = false;
                        break;
                    }else{}

                    if(1 != mid_arr->FB_TM_Halt[id].Done)
                    {
                        FB->all_axis_done = 0;//存在一个轴没完成，则轴组没完成
                    }
                }

                if(1 == FB->all_axis_done && FB->Error != true)
                {
                    *axesgroup_is_transition_motion = 0;
                    FB->Done =false;
                    FB->run_flag = false;

                    if(true == FB->CommandAborted)
                    {
                        *axesgroup_busy = 0;//延后一个周期，确保TMNone初速度一定为0
                        FB->TM_run_flag = false;
                        console_printf("\n TMNone-abort  done--------\n");
                    }

                    FB->Active = false;
                    FB->CommandAborted = true;
                    *run_next = 1;
                }
            }
            else if(2 == FB->tm_mode)
            {
                for(int id = 0; id<*axis_sum_ingroup;id++)
                {
                    if(0 == mid_arr->axis_should_motion[id])
                    {
                        continue;
                    }
                    if(axesgroup_axis_able_blending[id]!= 1)
                    {
                        continue;
                    }
                    if(mid_arr->FB_TM_MoveContiousAbsolute[id].Execute != 1)// &&FB->Execute == 1)
                    {
                        console_printf("\n-------------PTP-TM_run_flag:-----------------\n");
                        console_printf("id = %d if(FB_TM_MoveContiousAbsolute[id].Execute =%d &&FB->Execute=%d)mid_arr->aim_pulse[id]=%lf \n",id,mid_arr->FB_TM_MoveContiousAbsolute[id].Execute,FB->Execute,mid_arr->aim_pulse[id]);
                        if(mid_arr->axis_max_vel[id] < 0.000001)
                        {
                            continue;
                        }
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Execute = 1 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].execute_before = 0 ;
//输入量
                        if(mid_arr->aim_pulse[id]>0)
                        {
                            mid_arr->FB_TM_MoveContiousAbsolute[id].Position = (long)mid_arr->aim_pulse[id]+1 ;
                        }
                        else if(mid_arr->aim_pulse[id] == 0)
                        {
                            mid_arr->FB_TM_MoveContiousAbsolute[id].Position = 0 ;
                        }
                        else
                        {
                            mid_arr->FB_TM_MoveContiousAbsolute[id].Position = (long)mid_arr->aim_pulse[id]-1 ;
                        }

                        //所有函数的输入的单位是秒，内部计算是毫秒，所以需要转换为秒的单位
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Velocity = mid_arr->axis_max_vel[id] *1000.0;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].EndVelocity = mid_arr->axis_max_vel[id] *1000.0;
                        if(mid_arr->axis_aim_direction[id] == -1)
                        {
                            mid_arr->FB_TM_MoveContiousAbsolute[id].EndVelocity = mid_arr->FB_TM_MoveContiousAbsolute[id].EndVelocity*(-1);
                        }
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Acceleration = mid_arr->every_axis_maxacc[id] * 1000000.0;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Deceleration = mid_arr->every_axis_maxdec[id] * 1000000.0 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Jerk = mid_arr->every_axis_jerk[id] * 1000000000.0 ;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].BufferMode = mcAborting;
                        mid_arr->FB_TM_MoveContiousAbsolute[id].Axis_num = axis_num_ingroup[id] ;
                        console_printf("FB_TM_MoveContiousAbsolute: id=%d   Pos = %lf Vel=%lf EndVelocity = %lf ACC=%lf DEC=%lf JERK=%lf\n",id,mid_arr->FB_TM_MoveContiousAbsolute[id].Position,
                               mid_arr->FB_TM_MoveContiousAbsolute[id].Velocity,mid_arr->FB_TM_MoveContiousAbsolute[id].EndVelocity,mid_arr->FB_TM_MoveContiousAbsolute[id].Acceleration,mid_arr->FB_TM_MoveContiousAbsolute[id].Deceleration,mid_arr->FB_TM_MoveContiousAbsolute[id].Jerk);
                    }

                    axis_n = axis_num_ingroup[id];
                    //axis_state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + STATE]);
                    //*axis_state = MC_Standstill;
                    FBDMC_MoveContiousAbsolute(Task, FBIndex, &mid_arr->FB_TM_MoveContiousAbsolute[id]);
                    //*axis_state = MC_Synchronized_Motion;

//输出量
                    if(mid_arr->FB_TM_MoveContiousAbsolute[id].Error == 1)
                    {
                        FB->run_flag = false;
                        FB->TM_run_flag = false;
                        FB->Error = true;

                        if(mid_arr->FB_TM_MoveContiousAbsolute[id].ErrorID == StateError)
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_StateError;
                        }
                        else if(mid_arr->FB_TM_MoveContiousAbsolute[id].ErrorID == ParameterError)
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_ParameterError;
                        }
                        else
                        {
                            FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_OtherError;
                        }

                        FB->run_numberF = 0;
                        FB->Active = false;
                        FB->Done = false;
                        FB->Busy = false;
                        console_printf("\nif(mid_arr->FB_TM_MoveContiousAbsolute[%d].Error == 1):axis_error = %d\n",id,mid_arr->FB_TM_MoveContiousAbsolute[id].ErrorID);
                        break;
                    }
                    else  if(mid_arr->FB_TM_MoveContiousAbsolute[id].CommandAborted == 1)
                    {

                        FB->run_flag = false;
                        FB->TM_run_flag = false;
                        FB->Error = true;
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_CommandAborted_Error;
                        FB->run_numberF = 0;
                        FB->Active = false;
                        FB->Done = false;
                        FB->Busy = false;
                        break;
                    }else{}

                    if(1 == mid_arr->FB_TM_MoveContiousAbsolute[id].InVelocity)
                    {
                        FB->all_axis_done = 1;//存在一个轴完成，则轴组完成
                    }
                }

                //运行时间到了（防止跑过头了）或者所有的都到达指定速度就会停止
                if((FB->t_now >= FB->max_finish_time || 1 == FB->all_axis_done) && FB->Error != true)
                {
                    *axesgroup_is_transition_motion = 0;
                    FB->Done =true;
                    //FB->run_flag = false;
                    //FB->TM_run_flag = false;
                    *axesgroup_busy = 0;
                    FB->Active = false;
                    FB->CommandAborted = false;
                    *run_next = 1;
                }
            }
            FB->t_now+=(float)Task->taskPeriod / 1000;//默认一周期为1ms
        }
    }

///run_flag 负责每周期的运动
    if(FB->run_flag == true)
    {
        //*axesgroup_busy = 1;
        mid_arr = (struct MoveDirectAbsolute_MidArray *)FB->MidArray_Addr;
        if(*axesgroup_run_number != FB->run_numberF)     /**运动被打断*/
        {
            FB->CommandAborted = true;
            FB->run_flag = false;
            FB->TM_run_flag = false;

            FB->run_numberF = 0;
            FB->Active = false;
            FB->Done = false;
            FB->Busy = false;
            if(*inter_flag == 1)
            {
                FB->Active = true;
            }
        }
        else
        {
            FB->Active = true;
            *axesgroup_busy = 1;
            FB->all_axis_done = 1;
            axis_dec_sum = 0;

            //运行movevel的代码
            for(int id = 0; id<*axis_sum_ingroup;id++)
            {
                if(0 == mid_arr->axis_should_motion[id])
                {
                    continue;
                }
                if(FB->t_now >= mid_arr->MoveVel_time[id])
                {
                    continue;
                }

                //启动movevel
                FB->all_axis_done = 0;
                if(mid_arr->FB_MC_MoveVelocity[id].Execute != 1 &&FB->Execute == 1)
                {
                    //速度太小
                    if(mid_arr->axis_max_vel[id] < 0.000001)
                    {
                        continue;
                    }
                   // console_printf("\n-------------PTP-runflag:-----------------\n");
                  //  console_printf("id = %d if(mid_arr->FB_MC_MoveVelocity[id].Execute =%d &&FB->Execute=%d) \n",id,mid_arr->FB_MC_MoveVelocity[id].Execute,FB->Execute);


                    mid_arr->FB_MoveAbsolute[id].Execute = 0 ;
                    mid_arr->FB_MoveAbsolute[id].execute_before = 0 ;
                    mid_arr->FB_MC_MoveVelocity[id].Execute = 1 ;
                    mid_arr->FB_MC_MoveVelocity[id].execute_before = 0 ;
                    //输入量
                    mid_arr->FB_MC_MoveVelocity[id].Velocity = mid_arr->axis_max_vel[id] * 1000.0 ;
                    if(mid_arr->axis_aim_direction[id] == -1)
                    {
                        mid_arr->FB_MC_MoveVelocity[id].Velocity = mid_arr->FB_MC_MoveVelocity[id].Velocity*(-1);
                    }

                    mid_arr->FB_MC_MoveVelocity[id].Acceleration = mid_arr->every_axis_maxacc[id] * 1000000.0 ;
                    mid_arr->FB_MC_MoveVelocity[id].Deceleration = mid_arr->every_axis_maxdec[id]* 1000000.0 ;
                    mid_arr->FB_MC_MoveVelocity[id].Jerk = mid_arr->MoveVel_JERK1[id] * 1000000000.0 ;
                    if(mid_arr->FB_MC_MoveVelocity[id].Jerk >= axesgroup->f32_Joint_MaxJerk[id]-1)
                    {//-1是为了防止出现浮点数计算误差
                        mid_arr->FB_MC_MoveVelocity[id].Jerk = axesgroup->f32_Joint_MaxJerk[id]-1;
                    }
                    mid_arr->FB_MC_MoveVelocity[id].BufferMode = mcAborting;
                    mid_arr->FB_MC_MoveVelocity[id].Axis_num = axis_num_ingroup[id] ;
                 //   console_printf("id=%d   Vel=%lf ACC=%lf DEC=%lf JERK=%lf\n",id,mid_arr->FB_MC_MoveVelocity[id].Velocity,mid_arr->FB_MC_MoveVelocity[id].Acceleration,mid_arr->FB_MC_MoveVelocity[id].Deceleration,mid_arr->FB_MC_MoveVelocity[id].Jerk);
                }

                axis_n = axis_num_ingroup[id];
               // axis_state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + STATE]);
                //*axis_state = MC_Standstill;
                FBDMC_MoveVelocity(Task, FBIndex, &mid_arr->FB_MC_MoveVelocity[id]);
               // *axis_state = MC_Synchronized_Motion;

                //输出量
                if(mid_arr->FB_MC_MoveVelocity[id].Error == 1)
                {
                    FB->run_flag = false;
                    FB->TM_run_flag = false;
                    FB->Error = true;

                    if(mid_arr->FB_MC_MoveVelocity[id].ErrorID == StateError)
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_StateError;
                    }
                    else if(mid_arr->FB_MC_MoveVelocity[id].ErrorID == ParameterError)
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_ParameterError;
                    }
                    else
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_OtherError;
                    }

                    FB->run_numberF = 0;
                    FB->Active = false;
                    FB->Done = false;
                    FB->Busy = false;
                   // console_printf("\nif(mid_arr->FB_MC_MoveVelocity[%d].Error == 1):axis_error = %d\n",id,mid_arr->FB_MC_MoveVelocity[id].ErrorID);
                    break;
                }
                else  if(mid_arr->FB_MC_MoveVelocity[id].CommandAborted == 1 && false == FB->TM_run_flag && FB->t_now < mid_arr->MoveVel_time[id] - 1)
                {

                    FB->run_flag = false;
                    FB->TM_run_flag = false;
                    FB->Error = true;
                    FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_CommandAborted_Error;
                    FB->run_numberF = 0;
                    FB->Active = false;
                    FB->Done = false;
                    FB->Busy = false;
                    break;
                }else{}

            }


            //运行moveabs的代码

            for(int id = 0; id<*axis_sum_ingroup;id++)
            {
                if(0 == mid_arr->axis_should_motion[id])
                {
                    continue;
                }
                if(FB->t_now < mid_arr->MoveVel_time[id])
                {
                    continue;
                }
                //启动moveabs 如果在movevel阶段被混承，则不需要启动
                if(mid_arr->FB_MoveAbsolute[id].Execute != 1 &&FB->Execute == 1 && mid_arr->FB_TM_Halt[id].Execute != 1 && mid_arr->FB_TM_MoveContiousAbsolute[id].Execute != 1)
                {

                    //速度太小
                    if(mid_arr->axis_max_vel[id] < 0.000001)
                    {
                 //       console_printf("id=%d mid_arr->axis_max_vel[id] = %f, <0.000001 \n",id,mid_arr->axis_max_vel[id]);
                        continue;
                    }

                    mid_arr->FB_MoveAbsolute[id].Execute = 1 ;
                    mid_arr->FB_MoveAbsolute[id].execute_before = 0 ;
                    mid_arr->FB_MC_MoveVelocity[id].Execute = 0 ;
                    mid_arr->FB_MC_MoveVelocity[id].execute_before = 0 ;
                    //输入量

                    mid_arr->FB_MoveAbsolute[id].Position = mid_arr->aim_pulse[id];
                    mid_arr->FB_MoveAbsolute[id].Velocity = mid_arr->axis_max_vel[id] * 1000.0;

                    mid_arr->FB_MoveAbsolute[id].Acceleration = mid_arr->every_axis_maxacc[id] * 1000000.0 ;
                    mid_arr->FB_MoveAbsolute[id].Deceleration = mid_arr->every_axis_maxdec[id] * 1000000.0 ;

                    //mid_arr->MoveVel_time[id]不为0，需要改变jerk，0.001秒 || 不运行movevel，但是要调整jerk
                    if(mid_arr->MoveVel_time[id] > 0.1 || mid_arr->MoveVel_time[id] < 0)
                    {
                        mid_arr->FB_MoveAbsolute[id].Jerk = (long)(mid_arr->MoveAbs_JERK2[id] * 1000000000);
                    }
                    else
                    {
                        mid_arr->FB_MoveAbsolute[id].Jerk = (long)(mid_arr->every_axis_jerk[id] * 1000000000) ;
                    }
                    if(mid_arr->FB_MoveAbsolute[id].Jerk >= axesgroup->f32_Joint_MaxJerk[id]-1)
                    {//-1是为了防止出现浮点数计算误差
                        mid_arr->FB_MoveAbsolute[id].Jerk = axesgroup->f32_Joint_MaxJerk[id]-1;
                    }

                    mid_arr->FB_MoveAbsolute[id].BufferMode = mcAborting;
                    mid_arr->FB_MoveAbsolute[id].Axis_num = axis_num_ingroup[id] ;
                  //  console_printf("PTP-runflag:id=%d Pos = %lf Vel=%lf ACC=%lf DEC=%lf JERK=%lf\n",id,mid_arr->FB_MoveAbsolute[id].Position,
                  //         mid_arr->FB_MoveAbsolute[id].Velocity,mid_arr->FB_MoveAbsolute[id].Acceleration,mid_arr->FB_MoveAbsolute[id].Deceleration, mid_arr->FB_MoveAbsolute[id].Jerk);
                }

                axis_n = axis_num_ingroup[id];
               // axis_state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + STATE]);
              //  *axis_state = MC_Standstill;
                //console_printf("\n11111111111111111111111111.........................................\n");
                FBDMC_MoveAbsolute(Task, FBIndex, &mid_arr->FB_MoveAbsolute[id]);
                //console_printf("\n2222222222222222222222222.........................................\n");
               // *axis_state = MC_Synchronized_Motion;

                //输出量
                if(mid_arr->FB_MoveAbsolute[id].Error == 1)
                {
                    FB->run_flag = false;
                    FB->TM_run_flag = false;
                    FB->Error = true;

                    if(mid_arr->FB_MoveAbsolute[id].ErrorID == StateError)
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_StateError;
                    }
                    else if(mid_arr->FB_MoveAbsolute[id].ErrorID == ParameterError)
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_ParameterError;
                    }
                    else
                    {
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_OtherError;
                    }

                    FB->run_numberF = 0;
                    FB->Active = false;
                    FB->Done = false;
                    FB->Busy = false;
                  //  console_printf("\nif(mid_arr->FB_MoveAbsolute[%d].Error == 1):axis_error = %d\n",id,mid_arr->FB_MoveAbsolute[id].ErrorID);
                    break;
                }
                else  if(mid_arr->FB_MoveAbsolute[id].CommandAborted == 1 && false == FB->TM_run_flag)
                {
                //    console_printf("\nif(mid_arr->FB_MoveAbsolute[%d].CommandAborted == 1):axis_error = %d\n",id,mid_arr->FB_MoveAbsolute[id].ErrorID);
                    FB->run_flag = false;
                    FB->TM_run_flag = false;
                    FB->Error = true;

                    FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_CommandAborted_Error;
                    FB->run_numberF = 0;
                    FB->Active = false;
                    FB->Done = false;
                    FB->Busy = false;
                    break;
                }else{}

                if(1 != mid_arr->FB_MoveAbsolute[id].Done)
                {
                    FB->all_axis_done = 0;//存在一个轴没完成，则轴组没完成
                }

                //moveabs在减速阶段
                // move_state 为0也行：初速度太大的，无法调整时间，因为在初速度下降为最大速度之前就已经走完了所有路程 即vs[i] / acc > FB->max_finish_time
                //在把反向速度降为0的过程中move_state=0
                if(3 == mid_arr->FB_MoveAbsolute[id].move_state)
                {
                    axis_dec_sum=axis_dec_sum+1;
                }
                else if(0 == mid_arr->FB_MoveAbsolute[id].move_state)
                {
                    if(mid_arr->FB_MoveAbsolute[id].Jerk == 0  && mid_arr->FB_MoveAbsolute[id].t_now >= (mid_arr->FB_MoveAbsolute[id].rt1+1))
                    {
                        axis_dec_sum=axis_dec_sum+1;
                    }
                    else if(mid_arr->FB_MoveAbsolute[id].Jerk != 0 && mid_arr->FB_MoveAbsolute[id].t_now >= (mid_arr->FB_MoveAbsolute[id].rt1+mid_arr->FB_MoveAbsolute[id].rt2+mid_arr->FB_MoveAbsolute[id].rt3+1))
                    {
                        axis_dec_sum=axis_dec_sum+1;
                    }

                }
            }


            //if(axis_dec_sum > (*axis_sum_ingroup/2))
            if(0 == FB->move_state && FB->t_now >= (FB->max_finish_time*(1 - *axesgroup_transitionparameter/3)))
            {
              //  console_printf("\n==============if(FB->t_now >= (FB->max_finish_time*(1 - *axesgroup_transitionparameter = %lf/3)))=============\n",*axesgroup_transitionparameter);
              //  console_printf("if(FB->run_flag=%d && *axesgroup_buffer_busy =%d && !FB->buffer_run=%d && FB->Done =%d && FB->CommandAborted =%d)*axesgroup_transitionmode=%d *axesgroup_buffermode = %d *axesgroup_buffer_motion_type = %d\n",FB->run_flag,*axesgroup_buffer_busy,FB->buffer_run,FB->Done,FB->CommandAborted,*axesgroup_transitionmode,*axesgroup_buffermode,*axesgroup_buffer_motion_type);

                //console_printf("\n=============================if(axis_dec_sum > (*axis_sum_ingroup/2))========================\n");
                FB->move_state = 1;//可以进行混承
            }

            //if((FB->t_now >= FB->max_finish_time || 1 == FB->all_axis_done) && FB->Error != true)
            if((FB->t_now >= FB->max_finish_time || 1 == FB->all_axis_done) && FB->Error != true && false == FB->TM_run_flag)
            {
//                if(true == FB->Done)不应该在这里强制末速度为0，因为done已经true了，不能再处理 axesgroup_busy
//                {
//                    *axesgroup_busy = 0;//延后一个周期，确保末速度一定为0
//                    FB->run_flag = false;
//                }
                FB->Done = true;
                *axesgroup_now_motion_type = NO_TYPE;
                FB->run_flag = false;
                FB->TM_run_flag = false;
                *axesgroup_busy = 0;
                FB->Active = false;
                FB->CommandAborted = false;
                *run_next = 1;
               // console_printf("\n---------- FBDMC_MoveDirectAbsolute- FB->Done = true;-------\n");

            }

			if(true == FB->Done)
            {
                FB->run_flag = false;
				*axesgroup_now_motion_type = NO_TYPE;

                FB->TM_run_flag = false;
                *axesgroup_busy = 0;
                FB->Active = false;
                FB->CommandAborted = false;
                *run_next = 1;
          //      console_printf("\n---------- FBDMC_MoveDirectAbsolute- TM_FB->Done = true;-------\n");

            }

			if(false == FB->TM_run_flag)
			{
				FB->t_now+=(float)Task->taskPeriod / 1000;//默认一周期为1ms
			}

        }
    }

    //运动完成之后，busy变成false
    if(FB->Done == true)
    {
        FB->Busy = false;
    }
    else if(FB->exe || FB->run_flag || FB->TM_run_flag)
    {
        FB->Busy = true;
    }
    else
    {
        FB->Busy = false;
    }

    if(!FB->Execute && !FB->run_flag && !FB->buffer && !FB->TM_run_flag && FB->Error == true && 1 == *Axesgroup_GroupError && FB->ErrorID != AXESGROUP_MOTION_FB_WARNING)
    {
        //执行到这里的时候，距离*Axesgroup_GroupError置为1，已经至少过去了一个周期，后续功能块都停止继续运动
        FB->Error = false;
        FB->ErrorID = 0;
        *Axesgroup_GroupError = 0;
        *Axesgroup_GroupErrorID = NoGroupError;
    }

    if(FB->Error == true && FB->ErrorID != AXESGROUP_MOTION_FB_WARNING && *Axesgroup_GroupError != 1)
    {//该运动报错，后续运动停止运行
        *Axesgroup_GroupError = 1;
        *Axesgroup_GroupErrorID = FB->ErrorID;
        *axesgroup_busy = 0;
        *axesgroup_buffer_busy = 0;
    //    console_printf("\nif(FB->Error == true && FB->ErrorID = %d && *Axesgroup_GroupError != 1)\n",FB->ErrorID);
    }




    FB->AxesGroupOut = FB->AxesGroup;
    //console_printf("\n----------quit FBDMC_MoveDirectAbsolute------------\n");
#endif

}

